function FindBackground(windowSize, spacingPortion) {
    this.window = null;
    this.image = null;
    this.windowSize = windowSize;
    this.spacing = Math.round(windowSize / spacingPortion);
    this.brightnessArray = new Array(this.windowSize * this.windowSize);
    this.verbosity = 1;
    this.generatePreview = true;

    // Add property for exclusion areas
    this.exclusionAreas = [];

    this.filterAverage = true;
    this.filterStandardDeviation = true;
    this.filterMedianAverageAbsoluteDifference = true;
    this.filterPoissonIndex = false;
    this.filterForObjects = true;

    let filterAverageValue = 1.0;
    let filterStandardDeviationValue = 1.0;
    let filterMedianAverageAbsoluteDifferenceValue = 1.0;
    let filterPoissonIndexValue = 1.0;
    let filterForObjectsValue = 1.0;

    let filterStandardDeviationCap = 0.3333333;
    let filterMedianAverageAbsoluteDifferenceCap = 0.1;
    let filterPoissonIndexCap = 0.2;

    let filterStandardDeviationNormalization = 1.0;
    let filterMedianAverageAbsoluteDifferenceNormalization = 1.0;
    let filterPoissonIndexNormalization = 1.0;

    let filterForObjectsThreshold = 0.0;

    this.setTarget = function(window) {
        if (window.isNull)
            throw new Error("The selected image is invalid. Please select a valid image.");
        this.window = window;
        this.image = window.mainView.image;
    }

    this.setWindowSize = function(windowSize) {
        this.windowSize = windowSize;
        this.spacing = -1;
    }

    this.setSpacingPortion = function(spacingPortion) {
        this.spacing = Number((this.windowSize / spacingPortion).toFixed(0));
    }

    this.searchBackground = function(printInformationToConsole, previewName) {
        if (this.spacing == -1)
            throw new Error("Spacing is not set. Please set the spacing before starting the search.");

        //this.window.mainView.beginProcess();

        let objectFilteringWasOn = this.filterForObjects;
        this.filterForObjects = false;

        if (this.filterForObjects)
            setupObjectFilter();

        log("Setting up normalization constants...");
        setupFilterNormalization();

        this.filterForObjects = objectFilteringWasOn;

        let lowestX = 0;
        let lowestY = 0;
        let lowestScore = Infinity;

        let optimizationCount = 0;
        if (this.filterAverage)
            optimizationCount++;
        if (this.filterStandardDeviation)
            optimizationCount++;
        if (this.filterMedianAverageAbsoluteDifference)
            optimizationCount++;

    let outerIterations = Math.ceil((this.image.width - 2 * this.windowSize) / this.spacing);
    let innerIterations = Math.ceil((this.image.height - 2 * this.windowSize) / this.spacing);
    let totalIterations = 0;
    for (let x = windowSize; x < this.image.width - this.windowSize; x += this.spacing) {
        for (let y = windowSize; y < this.image.height - this.windowSize; y += this.spacing) {
            let point = { x: x, y: y };
            if (!this.isPointInAnyExclusionArea(point, this.exclusionAreas)) {
                totalIterations++;
            }
        }
    }
    let divisor = Math.floor(totalIterations / 100);
    let currentIteration = 0;

        console.abortEnabled = true;

        if (this.verbosity == 1) {
            console.show();
            console.writeln("Processing started...");
            console.writeln("Exclusion areas: " + JSON.stringify(this.exclusionAreas));
            console.writeln("|....................................................................................................|");
            console.write("|");
        }

        for (let x = windowSize; x < this.image.width - this.windowSize; x += this.spacing) {
            for (var y = windowSize; y < this.image.height - this.windowSize; y += this.spacing) {
                let point = { x: x, y: y };
                 if (this.isPointInAnyExclusionArea(point, this.exclusionAreas)) {
                     continue; // Skip points inside the exclusion areas
                 }

                calculateFilterValues(x, y);
                let score = getScore();

                if (score < lowestScore) {
                    lowestScore = score;
                    lowestX = x;
                    lowestY = y;
                }

                currentIteration++;
                if (currentIteration % divisor == 0)
                    console.write(".");
            }
            CoreApplication.processEvents();
            if (console.abortRequested) {
                console.writeln("|");
                console.writeln("Processing aborted by user.");
                return;
            }
        }

        log("|");

        log("Refining solution using gradient descent...");

        let refinedSolution = gradientDescent(lowestX, lowestY);
        lowestX = refinedSolution[0];
        lowestY = refinedSolution[1];

        log("Gradient descent finished, found final solution.");

        this.lastResult = new Rect(
            lowestX,
            lowestY,
            lowestX + this.windowSize,
            lowestY + this.windowSize
        );

        if (this.generatePreview)
            this.window.createPreview(lowestX, lowestY, lowestX + this.windowSize, lowestY + this.windowSize, previewName || "Background");

        if (printInformationToConsole)
            printInformation(lowestX, lowestY);

        //this.window.mainView.endProcess();
    }

    this.fastSearchBackground = function(initialSize, targetCount, printInformationToConsole, previewName) {
        if (this.spacing == -1)
            throw new Error("Spacing is not set. Please set the spacing before starting the fast search.");

        //this.window.mainView.beginProcess();
        console.show();
        console.abortEnabled = true;
        log("Fast search started...");

        let objectFilteringWasOn = this.filterForObjects;
        this.filterForObjects = false;

        log("Setting up normalization constants...");
        setupFilterNormalization();

        let oldSpacing = this.spacing;
        this.spacing = initialSize;

        let countWidth = Math.ceil((this.image.width - 2 * this.windowSize) / this.spacing);
        let countHeight = Math.ceil((this.image.height - 2 * this.windowSize) / this.spacing);
        let totalIterations = countWidth * countHeight;
        let averages = new Array(totalIterations);

console.writeln("Looking for starting points...");
console.writeln("Exclusion areas: " + JSON.stringify(this.exclusionAreas));


for (var x = this.spacing; x < this.image.width - this.spacing; x += this.spacing) {
    for (var y = this.spacing; y < this.image.height - this.spacing; y += this.spacing) {
        let point = { x: x, y: y };

        if (this.isPointInAnyExclusionArea(point, this.exclusionAreas)) {
            continue; // Skip points inside the exclusion areas
        }

        calculateFilterValues(x, y);
        let score = getScore();
        averages[(x - this.spacing) / this.spacing * countHeight + (y - this.spacing) / this.spacing] = [x, y, score];
    }
    CoreApplication.processEvents();
    if (console.abortRequested) {
        throw new Error("Processing aborted by user.");
    }
}

console.writeln("Finished looking for starting points.");



        this.spacing = oldSpacing;

        averages = averages.sort((a, b) => a[2] - b[2]);
        averages = averages.slice(0, targetCount);

        log("Selected the " + targetCount + " best starting points.");
        this.filterForObjects = objectFilteringWasOn;

        let results = new Array(targetCount);

        for (var i = 0; i < averages.length; i++) {
            log("Optimizing window " + (i + 1) + " of " + targetCount + "...");
            let result = gradientDescent(averages[i][0], averages[i][1]);
            results[i] = result;
            CoreApplication.processEvents();
            if (console.abortRequested) {
                throw new Error("Processing aborted by user.");
            }
        }

        results = results.sort((a, b) => a[2] - b[2]);

        log("Selected the best result.");

        this.lastResult = new Rect(
            results[0][0],
            results[0][1],
            results[0][0] + this.windowSize,
            results[0][1] + this.windowSize
        );

        if (this.generatePreview)
            this.window.createPreview(results[0][0], results[0][1], results[0][0] + this.windowSize, results[0][1] + this.windowSize, previewName || "Background");

        if (printInformationToConsole)
            printInformation(results[0][0], results[0][1]);

        //this.window.mainView.endProcess();
    }

// Function to check if a point is inside any exclusion area
this.isPointInAnyExclusionArea = function(point, exclusionAreas) {
    let result = exclusionAreas.some(area => this.isPointInExclusionArea(point, area));
    return result;
};

// Function to check if a point is inside an exclusion area
this.isPointInExclusionArea = function(point, exclusionArea) {
    let result = point.x >= exclusionArea.left && point.x <= exclusionArea.right && point.y >= exclusionArea.top && point.y <= exclusionArea.bottom;
    return result;
};


    let gradientDescent = (x, y) => {
        this.spacing = parseFloat(this.spacing);
        x = parseFloat(x);
        y = parseFloat(y);

        let lowestScore = Infinity;
        let improved = true;
        let moveRate = 1.0;

        let lowestX = x;
        let lowestY = y;

        let iterationCounter = 0;
        let rects = [];

        while (moveRate * parseFloat(this.spacing) >= 1.0) {
            rects.push([x, y]);
            iterationCounter++;

            improved = false;

            for (let dx = -1.0; dx <= 1.0; dx += 1.0) {
                for (let dy = -1.0; dy <= 1.0; dy += 1.0) {
                    let newX = Math.round(x + dx * this.spacing * moveRate);
                    let newY = Math.round(y + dy * this.spacing * moveRate);

                    if (newX - this.windowSize < 0 || newX + this.windowSize >= this.image.width || newY - this.windowSize < 0 || newY + this.windowSize >= this.image.height)
                        continue;

                    let point = { x: newX, y: newY };
                    if (this.isPointInAnyExclusionArea(point, this.exclusionAreas)) {
                        continue; // Skip points inside the exclusion areas
                    }

                    calculateFilterValues(newX, newY);
                    let score = getScore();

                    if (score < lowestScore) {
                        lowestScore = score;
                        lowestX = newX;
                        lowestY = newY;
                        improved = true;
                    }
                }
            }

            if (!improved)
                moveRate *= 0.5;

            x = lowestX;
            y = lowestY;

            CoreApplication.processEvents();
            if (console.abortRequested) {
                throw new Error("Processing aborted by user.");
            }
        }

        return [lowestX, lowestY, lowestScore];
    };

    let calculateFilterValues = (x, y) => {
        if (this.filterAverage)
            calculateAverage(x, y);
        if (this.filterStandardDeviation) {
            if (!this.filterAverage)
                calculateAverage(x, y);
            calculateStandardDeviation(x, y, filterAverageValue);
        }
        if (this.filterMedianAverageAbsoluteDifference) {
            if (!this.filterAverage && !this.filterStandardDeviation)
                calculateAverage(x, y);
            if (!this.filterStandardDeviation)
                calculateStandardDeviation(x, y, filterAverageValue);
            calculateMedianAverageAbsoluteDifference(x, y, filterAverageValue, filterStandardDeviationValue);
        }
        if (this.filterPoissonIndex)
            calculatePoissonIndex(x, y);
    };

    let printInformation = (lowestX, lowestY) => {
        calculateFilterValues(lowestX, lowestY);
        let score = getScore();
        console.noteln("\n\nProcessing finished!\n\n");
        let informationBrightnessArray = new Array(this.image.numberOfChannels);
        for (var i = 0; i < this.image.numberOfChannels; i++)
            informationBrightnessArray[i] = 0;

        for (var x = lowestX; x < lowestX + this.windowSize; x++)
            for (var y = lowestY; y < lowestY + this.windowSize; y++)
                for (var c = 0; c < this.image.numberOfChannels; c++)
                    informationBrightnessArray[c] += this.image.sample(x, y, c);

        for (var c = 0; c < this.image.numberOfChannels; c++)
            informationBrightnessArray[c] /= this.windowSize * this.windowSize;

        let highestValue = 0;
        for (var c = 0; c < this.image.numberOfChannels; c++)
            if (informationBrightnessArray[c] > highestValue)
                highestValue = informationBrightnessArray[c];

        let correctionConstants = new Array(this.image.numberOfChannels);
        for (var c = 0; c < this.image.numberOfChannels; c++)
            correctionConstants[c] = highestValue - informationBrightnessArray[c];

        console.writeln("Average channel brightness:");
        for (var c = 0; c < this.image.numberOfChannels; c++)
            console.writeln("\t[" + c + "]: " + informationBrightnessArray[c]);

        if (this.image.numberOfChannels > 1) {
            console.writeln("\nAdditive color correction constants:");
            for (var c = 0; c < this.image.numberOfChannels; c++)
                console.writeln("\t[" + c + "]: " + correctionConstants[c]);
        }

        console.writeln("\nROI coordinates:");
        console.writeln("\tX: " + lowestX);
        console.writeln("\tY: " + lowestY);
        console.writeln("\tWidth: " + this.windowSize);
        console.writeln("\tHeight: " + this.windowSize);

        console.writeln("\nQuality assessment: ");
        if (this.filterAverage)
            console.writeln("\tAverage brightness                 : " + filterAverageValue);
        if (this.filterStandardDeviation)
            console.writeln("\tStandard deviation                 : " + filterStandardDeviationValue);
        if (this.filterPoissonIndex)
            console.writeln("\tPoisson index                      : " + filterPoissonIndexValue);
        if (this.filterMedianAverageAbsoluteDifference)
            console.writeln(
                "\tMedian average absolute difference : " + filterMedianAverageAbsoluteDifferenceValue
            );
        console.writeln("\tScore                              : " + score);
        console.noteln("Background Found! Preview Created!");
    };

    let getScore = () => {
        let avgScore, stDevScore, maadScore, poissonScore;
        if (this.filterAverage) avgScore = 1 / filterAverageValue;
        if (this.filterStandardDeviation) stDevScore = 1 / filterStandardDeviationValue;
        if (this.filterMedianAverageAbsoluteDifference)
            maadScore = 1 / filterMedianAverageAbsoluteDifferenceValue;
        if (this.filterPoissonIndex) poissonScore = 1 / filterPoissonIndexValue;

        let score = 0;

        if (this.filterAverage) score += avgScore;

        if (this.filterStandardDeviation && this.filterAverage)
            score += Math.min(avgScore * filterStandardDeviationCap, filterStandardDeviationNormalization * stDevScore);
        else if (this.filterStandardDeviation) score += stDevScore * filterStandardDeviationNormalization;

        if (this.filterMedianAverageAbsoluteDifference && this.filterAverage)
            score += Math.min(
                avgScore * filterMedianAverageAbsoluteDifferenceCap,
                filterMedianAverageAbsoluteDifferenceNormalization * maadScore
            );
        else if (this.filterMedianAverageAbsoluteDifference)
            score += maadScore * filterMedianAverageAbsoluteDifferenceNormalization;

        if (this.filterPoissonIndex && this.filterAverage)
            score += Math.min(avgScore * filterPoissonIndexCap, filterPoissonIndexNormalization * poissonScore);
        else if (this.filterPoissonIndex) score += poissonScore * filterPoissonIndexNormalization;

        score = 1 / score;

        // if(this.filterForObjects)
        //     score *= filterForObjectsValue;

        return score;
    };

    let log = (message) => {
        if (this.verbosity == 1) console.writeln(message);
        CoreApplication.processEvents();
    };

    // let setupObjectFilter = () =>
    // {
    //     let detector = new StarDetector;
    //     detector.hotPixelFilterRadius = 1;
    //     detector.sensitivity = 1;
    //     detector.peakResponse = 1;
    //     detector.allowClusteredSources = true;
    //     detector.maxDistortion = 0;

    //     let stars = detector.stars(this.image);
    //     let lowestCenterIntensity = Infinity;
    //     for(var i = 0; i < stars.length; i++)
    //     {
    //         let centerIntensity = 0;
    //         for(var c = 0; c < this.image.numberOfChannels; c++)
    //             centerIntensity += this.image.sample(stars[i].pos.x, stars[i].pos.y, c);
    //         centerIntensity /= this.image.numberOfChannels;
    //         if(centerIntensity < lowestCenterIntensity)
    //             lowestCenterIntensity = centerIntensity;
    //     }

    //     filterForObjectsThreshold = lowestCenterIntensity;
    // }

    let setupFilterNormalization = () => {
        let tileSize = 500;
        let targetMedianValue = 0.5;
        let averageValues = [];
        let standardDeviationValues = [];
        let medianAverageAbsoluteDifferenceValues = [];
        let poissonIndexValues = [];

        for (var x = 0; x < this.image.width - tileSize; x += tileSize) {
            for (var y = 0; y < this.image.height - tileSize; y += tileSize) {
                calculateFilterValues(x, y);
                averageValues.push(filterAverageValue);
                standardDeviationValues.push(filterStandardDeviationValue);
                medianAverageAbsoluteDifferenceValues.push(filterMedianAverageAbsoluteDifferenceValue);
                poissonIndexValues.push(filterPoissonIndexValue);
            }
        }

        let indices = averageValues.map((_, index) => index);
        indices = indices.sort((a, b) => averageValues[a] - averageValues[b]);

        averageValues = reorderArray(averageValues, indices).slice(0, Math.floor(averageValues.length / 4));
        standardDeviationValues = reorderArray(standardDeviationValues, indices).slice(0, Math.floor(standardDeviationValues.length / 4));
        medianAverageAbsoluteDifferenceValues = reorderArray(medianAverageAbsoluteDifferenceValues, indices).slice(
            0,
            Math.floor(medianAverageAbsoluteDifferenceValues.length / 4)
        );
        poissonIndexValues = reorderArray(poissonIndexValues, indices).slice(0, Math.floor(poissonIndexValues.length / 4));

        let medianAverageScore = 1 / averageValues[Math.floor(averageValues.length / 2)];
        let medianStandardDeviationScore = 1 / standardDeviationValues[Math.floor(standardDeviationValues.length / 2)];
        let medianMedianAverageAbsoluteDifferenceScore =
            1 / medianAverageAbsoluteDifferenceValues[Math.floor(medianAverageAbsoluteDifferenceValues.length / 2)];
        let medianPoissonIndexScore = 1 / poissonIndexValues[Math.floor(poissonIndexValues.length / 2)];

        filterStandardDeviationNormalization =
            (targetMedianValue * filterStandardDeviationCap * medianAverageScore) / medianStandardDeviationScore;
        filterMedianAverageAbsoluteDifferenceNormalization =
            (targetMedianValue * filterMedianAverageAbsoluteDifferenceCap * medianAverageScore) /
            medianMedianAverageAbsoluteDifferenceScore;
        filterPoissonIndexNormalization =
            (targetMedianValue * filterPoissonIndexCap * medianAverageScore) / medianPoissonIndexScore;
    };

    let reorderArray = (array, indices) => {
        let newArray = new Array(array.length);
        for (var i = 0; i < array.length; i++) newArray[i] = array[indices[i]];
        return newArray;
    };

    let calculateAverage = (x, y) => {
        let average = 0;

        for (let dx = 0; dx < this.windowSize; dx++)
            for (let dy = 0; dy < this.windowSize; dy++)
                for (var c = 0; c < this.image.numberOfChannels; c++)
                    average += this.image.sample(x + dx, y + dy, c);

        filterAverageValue = average / (this.windowSize * this.windowSize * this.image.numberOfChannels);
    };

    let calculateStandardDeviation = (x, y, average) => {
        let standardDeviation = 0;
        let pixelBrightness = 0;

        for (var dx = 0; dx < this.windowSize; dx++) {
            for (var dy = 0; dy < this.windowSize; dy++) {
                pixelBrightness = 0;
                for (var c = 0; c < this.image.numberOfChannels; c++) pixelBrightness += this.image.sample(x + dx, y + dy, c);

                standardDeviation += Math.pow(pixelBrightness - average, 2);
            }
        }

        filterStandardDeviationValue = Math.sqrt(
            standardDeviation / (this.windowSize * this.windowSize * this.image.numberOfChannels)
        );
    };

    let calculateMedianAverageAbsoluteDifference = (x, y, average, stDev) => {
        for (var dx = 0; dx < this.windowSize; dx++) {
            for (var dy = 0; dy < this.windowSize; dy++) {
                let pixelBrightness = 0;
                for (var c = 0; c < this.image.numberOfChannels; c++) pixelBrightness += this.image.sample(x + dx, y + dy, c);

                this.brightnessArray[dx * this.windowSize + dy] = pixelBrightness;
            }
        }

        this.brightnessArray = this.brightnessArray.sort((a, b) => a - b);

        let index = Math.floor(this.brightnessArray.length / 2);

        if (this.brightnessArray.length % 2)
            filterMedianAverageAbsoluteDifferenceValue = Math.abs(this.brightnessArray[index] - average) / stDev;
        else
            filterMedianAverageAbsoluteDifferenceValue =
                Math.abs((this.brightnessArray[index - 1] + this.brightnessArray[index]) / 2 - average) / stDev;
    };

    let calculatePoissonIndex = (x, y) => {
        let averages = new Array(this.image.numberOfChannels);
        for (var i = 0; i < averages.length; i++) averages[i] = 0;
        for (var dx = 0; dx < this.windowSize; dx++)
            for (var dy = 0; dy < this.windowSize; dy++)
                for (var c = 0; c < this.image.numberOfChannels; c++) averages[c] += this.image.sample(x + dx, y + dy, c);

        for (var i = 0; i < averages.length; i++) averages[i] /= this.windowSize * this.windowSize;

        let variances = new Array(this.image.numberOfChannels);
        for (var i = 0; i < variances.length; i++) variances[i] = 0;
        for (var dx = 0; dx < this.windowSize; dx++)
            for (var dy = 0; dy < this.windowSize; dy++)
                for (var c = 0; c < this.image.numberOfChannels; c++)
                    variances[c] += Math.pow(this.image.sample(x + dx, y + dy, c) - averages[i], 2);

        for (var i = 0; i < variances.length; i++) variances[i] /= this.windowSize * this.windowSize;

        let poissonIndexes = new Array(this.image.numberOfChannels);
        for (var i = 0; i < poissonIndexes.length; i++)
            poissonIndexes[i] = Math.abs(averages[i] - variances[i]) / averages[i];

        let poissonIndex = 0;
        for (var i = 0; i < poissonIndexes.length; i++) poissonIndex += poissonIndexes[i];

        filterPoissonIndexValue = Math.abs(poissonIndex / this.image.numberOfChannels - 1);
    };

    // Function to check if a point is inside any exclusion area
    this.isPointInAnyExclusionArea = function(point, exclusionAreas) {
        return exclusionAreas.some(area => this.isPointInExclusionArea(point, area));
    };

    // Function to check if a point is inside an exclusion area
    this.isPointInExclusionArea = function(point, exclusionArea) {
        if (!exclusionArea) return false;
        return (
            point.x >= exclusionArea.left &&
            point.x <= exclusionArea.right &&
            point.y >= exclusionArea.top &&
            point.y <= exclusionArea.bottom
        );
    };
}

function FindBackgroundUserDefined(windowSize, spacingPortion, userDefinedRegions) {
    this.window = null;
    this.image = null;
    this.windowSize = windowSize;
    this.spacing = Math.round(windowSize / spacingPortion);
    this.brightnessArray = new Array(this.windowSize * this.windowSize);
    this.verbosity = 1;
    this.generatePreview = true;
    this.userDefinedRegions = userDefinedRegions;

    this.filterAverage = true;
    this.filterStandardDeviation = true;
    this.filterMedianAverageAbsoluteDifference = true;
    this.filterPoissonIndex = false;
    this.filterForObjects = true;

    let filterAverageValue = 1.0;
    let filterStandardDeviationValue = 1.0;
    let filterMedianAverageAbsoluteDifferenceValue = 1.0;
    let filterPoissonIndexValue = 1.0;
    let filterForObjectsValue = 1.0;

    let filterStandardDeviationCap = 0.3333333;
    let filterMedianAverageAbsoluteDifferenceCap = 0.1;
    let filterPoissonIndexCap = 0.2;

    let filterStandardDeviationNormalization = 1.0;
    let filterMedianAverageAbsoluteDifferenceNormalization = 1.0;
    let filterPoissonIndexNormalization = 1.0;

    let filterForObjectsThreshold = 0.0;

    this.setTarget = function(window) {
        if (window.isNull)
            throw new Error("The selected image is invalid. Please select a valid image.");
        this.window = window;
        this.image = window.mainView.image;
    }

    this.setWindowSize = function(windowSize) {
        this.windowSize = windowSize;
        this.spacing = -1;
    }

    this.setSpacingPortion = function(spacingPortion) {
        this.spacing = Number((this.windowSize / spacingPortion).toFixed(0));
    }

    this.searchBackgroundUserDefined = function(printInformationToConsole, previewName) {
        if (this.spacing == -1)
            throw new Error("Spacing is not set. Please set the spacing before starting the search.");

        //this.window.mainView.beginProcess();

        let objectFilteringWasOn = this.filterForObjects;
        this.filterForObjects = false;

        if (this.filterForObjects)
            setupObjectFilter();

        log("Setting up normalization constants...");
        setupFilterNormalization();

        this.filterForObjects = objectFilteringWasOn;

        let lowestX = 0;
        let lowestY = 0;
        let lowestScore = Infinity;

        let optimizationCount = 0;
        if (this.filterAverage)
            optimizationCount++;
        if (this.filterStandardDeviation)
            optimizationCount++;
        if (this.filterMedianAverageAbsoluteDifference)
            optimizationCount++;

        console.abortEnabled = true;

        if (this.verbosity == 1) {
            console.show();
            console.writeln("Processing started...");
            console.writeln("|....................................................................................................|");
            console.write("|");
        }

        for (let region of this.userDefinedRegions) {
            let startX = Math.max(this.windowSize, region.left);
            let endX = Math.min(this.image.width - this.windowSize, region.right);
            let startY = Math.max(this.windowSize, region.top);
            let endY = Math.min(this.image.height - this.windowSize, region.bottom);

            console.writeln("Search bounds:");
            console.writeln("startX: " + startX + ", endX: " + endX);
            console.writeln("startY: " + startY + ", endY: " + endY);

            let outerIterations = Math.ceil((endX - startX) / this.spacing);
            let innerIterations = Math.ceil((endY - startY) / this.spacing);
            let totalIterations = outerIterations * innerIterations;
            let divisor = Math.floor(totalIterations / 100);
            let currentIteration = 0;

            for (let x = startX; x < endX; x += this.spacing) {
                for (let y = startY; y < endY; y += this.spacing) {
                    calculateFilterValues(x, y);
                    let score = getScore();

                    if (score < lowestScore) {
                        lowestScore = score;
                        lowestX = x;
                        lowestY = y;
                    }

                    currentIteration++;
                    if (currentIteration % divisor == 0)
                        console.write(".");
                }
                CoreApplication.processEvents();
                if (console.abortRequested) {
                    console.writeln("|");
                    console.writeln("Processing aborted by user.");
                    return;
                }
            }
        }

        log("|");

        log("Refining solution using gradient descent...");

        let refinedSolution = gradientDescent(lowestX, lowestY);
        lowestX = refinedSolution[0];
        lowestY = refinedSolution[1];

        log("Gradient descent finished, found final solution.");

        this.lastResult = new Rect(
            lowestX,
            lowestY,
            lowestX + this.windowSize,
            lowestY + this.windowSize
        );

        if (this.generatePreview)
            this.window.createPreview(lowestX, lowestY, lowestX + this.windowSize, lowestY + this.windowSize, previewName || "Background");

        if (printInformationToConsole)
            printInformation(lowestX, lowestY);

        //this.window.mainView.endProcess();
    }

    this.fastSearchBackgroundUserDefined = function(initialSize, targetCount, printInformationToConsole, previewName) {
        if (this.spacing == -1)
            throw new Error("Spacing is not set. Please set the spacing before starting the fast search.");

        //this.window.mainView.beginProcess();
        console.show();
        console.abortEnabled = true;
        log("Fast search started...");

        let objectFilteringWasOn = this.filterForObjects;
        this.filterForObjects = false;

        log("Setting up normalization constants...");
        setupFilterNormalization();

        let oldSpacing = this.spacing;
        this.spacing = initialSize;

        let averages = [];

        log("Looking for starting points...");

        for (let region of this.userDefinedRegions) {
            let startX = Math.max(this.windowSize, region.left);
            let endX = Math.min(this.image.width - this.windowSize, region.right);
            let startY = Math.max(this.windowSize, region.top);
            let endY = Math.min(this.image.height - this.windowSize, region.bottom);

            for (let x = startX; x < endX; x += this.spacing) {
                for (let y = startY; y < endY; y += this.spacing) {
                    calculateFilterValues(x, y);
                    let score = getScore();
                    averages.push([x, y, score]);
                }
                CoreApplication.processEvents();
                if (console.abortRequested) {
                    throw new Error("Processing aborted by user.");
                }
            }
        }

        this.spacing = oldSpacing;

        averages = averages.sort((a, b) => a[2] - b[2]);
        averages = averages.slice(0, targetCount);

        log("Selected the " + targetCount + " best starting points.");
        this.filterForObjects = objectFilteringWasOn;

        let results = new Array(targetCount);

        for (let i = 0; i < averages.length; i++) {
            log("Optimizing window " + (i + 1) + " of " + targetCount + "...");
            let result = gradientDescent(averages[i][0], averages[i][1]);
            results[i] = result;
            CoreApplication.processEvents();
            if (console.abortRequested) {
                throw new Error("Processing aborted by user.");
            }
        }

        results = results.sort((a, b) => a[2] - b[2]);

        log("Selected the best result.");

        this.lastResult = new Rect(
            results[0][0],
            results[0][1],
            results[0][0] + this.windowSize,
            results[0][1] + this.windowSize
        );

        if (this.generatePreview)
            this.window.createPreview(results[0][0], results[0][1], results[0][0] + this.windowSize, results[0][1] + this.windowSize, previewName || "Background");

        if (printInformationToConsole)
            printInformation(results[0][0], results[0][1]);

        //this.window.mainView.endProcess();
    }

    let gradientDescent = (x, y) => {
        this.spacing = parseFloat(this.spacing);
        x = parseFloat(x);
        y = parseFloat(y);

        let lowestScore = Infinity;
        let improved = true;
        let moveRate = 1.0;

        let lowestX = x;
        let lowestY = y;

        let iterationCounter = 0;
        let rects = [];

        while (moveRate * parseFloat(this.spacing) >= 1.0) {
            rects.push([x, y])
            iterationCounter++;

            improved = false;

            for (let dx = -1.0; dx <= 1.0; dx += 1.0) {
                for (let dy = -1.0; dy <= 1.0; dy += 1.0) {
                    let newX = Math.round(x + dx * this.spacing * moveRate);
                    let newY = Math.round(y + dy * this.spacing * moveRate);

                    if (newX - this.windowSize < 0 || newX + this.windowSize >= this.image.width || newY - this.windowSize < 0 || newY + this.windowSize >= this.image.height)
                        continue;

                    calculateFilterValues(newX, newY);
                    let score = getScore();

                    if (score < lowestScore) {
                        lowestScore = score;
                        lowestX = newX;
                        lowestY = newY;
                        improved = true;
                    }
                }
            }

            if (!improved)
                moveRate *= 0.5;

            x = lowestX;
            y = lowestY;

            CoreApplication.processEvents();
            if (console.abortRequested) {
                throw new Error("Processing aborted by user.");
            }
        }

        return [lowestX, lowestY, lowestScore];
    }

    let calculateFilterValues = (x, y) => {
        if (this.filterAverage) {
            calculateAverage(x, y);
        }
        if (this.filterStandardDeviation) {
            if (!this.filterAverage) calculateAverage(x, y);
            calculateStandardDeviation(x, y, filterAverageValue);
        }
        if (this.filterMedianAverageAbsoluteDifference) {
            if (!this.filterAverage && !this.filterStandardDeviation) calculateAverage(x, y);
            if (!this.filterStandardDeviation) calculateStandardDeviation(x, y, filterAverageValue);
            calculateMedianAverageAbsoluteDifference(x, y, filterAverageValue, filterStandardDeviationValue);
        }
        if (this.filterPoissonIndex) {
            calculatePoissonIndex(x, y);
        }
    }

    let printInformation = (lowestX, lowestY) => {
        calculateFilterValues(lowestX, lowestY);
        let score = getScore();
        console.noteln("\n\nProcessing finished!\n\n");
        let informationBrightnessArray = new Array(this.image.numberOfChannels);
        for (var i = 0; i < this.image.numberOfChannels; i++) {
            informationBrightnessArray[i] = 0;
        }
        for (var x = lowestX; x < lowestX + this.windowSize; x++) {
            for (var y = lowestY; y < lowestY + this.windowSize; y++) {
                for (var c = 0; c < this.image.numberOfChannels; c++) {
                    informationBrightnessArray[c] += this.image.sample(x, y, c);
                }
            }
        }
        for (var c = 0; c < this.image.numberOfChannels; c++) {
            informationBrightnessArray[c] /= (this.windowSize * this.windowSize);
        }
        let highestValue = 0;
        for (var c = 0; c < this.image.numberOfChannels; c++) {
            if (informationBrightnessArray[c] > highestValue) {
                highestValue = informationBrightnessArray[c];
            }
        }
        let correctionConstants = new Array(this.image.numberOfChannels);
        for (var c = 0; c < this.image.numberOfChannels; c++) {
            correctionConstants[c] = highestValue - informationBrightnessArray[c];
        }
        console.writeln("Average channel brightness:");
        for (var c = 0; c < this.image.numberOfChannels; c++) {
            console.writeln("\t[" + c + "]: " + informationBrightnessArray[c]);
        }
        if (this.image.numberOfChannels > 1) {
            console.writeln("\nAdditive color correction constants:");
            for (var c = 0; c < this.image.numberOfChannels; c++) {
                console.writeln("\t[" + c + "]: " + correctionConstants[c]);
            }
        }
        console.writeln("\nROI coordinates:");
        console.writeln("\tX: " + lowestX);
        console.writeln("\tY: " + lowestY);
        console.writeln("\tWidth: " + this.windowSize);
        console.writeln("\tHeight: " + this.windowSize);
        console.writeln("\nQuality assessment: ");
        if (this.filterAverage) {
            console.writeln("\tAverage brightness                 : " + filterAverageValue);
        }
        if (this.filterStandardDeviation) {
            console.writeln("\tStandard deviation                 : " + filterStandardDeviationValue);
        }
        if (this.filterPoissonIndex) {
            console.writeln("\tPoisson index                      : " + filterPoissonIndexValue);
        }
        if (this.filterMedianAverageAbsoluteDifference) {
            console.writeln("\tMedian average absolute difference : " + filterMedianAverageAbsoluteDifferenceValue);
        }
        console.writeln("\tScore                              : " + score);
        console.noteln("Background Found! Preview Created!");
    }

    let getScore = () => {
        let avgScore, stDevScore, maadScore, poissonScore;
        if (this.filterAverage) {
            avgScore = 1 / filterAverageValue;
        }
        if (this.filterStandardDeviation) {
            stDevScore = 1 / filterStandardDeviationValue;
        }
        if (this.filterMedianAverageAbsoluteDifference) {
            maadScore = 1 / filterMedianAverageAbsoluteDifferenceValue;
        }
        if (this.filterPoissonIndex) {
            poissonScore = 1 / filterPoissonIndexValue;
        }

        let score = 0;

        if (this.filterAverage) score += avgScore;
        if (this.filterStandardDeviation && this.filterAverage)
            score += Math.min(avgScore * filterStandardDeviationCap, filterStandardDeviationNormalization * stDevScore);
        else if (this.filterStandardDeviation)
            score += stDevScore * filterStandardDeviationNormalization;

        if (this.filterMedianAverageAbsoluteDifference && this.filterAverage)
            score += Math.min(avgScore * filterMedianAverageAbsoluteDifferenceCap, filterMedianAverageAbsoluteDifferenceNormalization * maadScore);
        else if (this.filterMedianAverageAbsoluteDifference)
            score += maadScore * filterMedianAverageAbsoluteDifferenceNormalization;

        if (this.filterPoissonIndex && this.filterAverage)
            score += Math.min(avgScore * filterPoissonIndexCap, filterPoissonIndexNormalization * poissonScore);
        else if (this.filterPoissonIndex)
            score += poissonScore * filterPoissonIndexNormalization;

        score = 1 / score;

        return score;
    }

    let log = (message) => {
        if (this.verbosity == 1)
            console.writeln(message);
        CoreApplication.processEvents();
    }

    let setupFilterNormalization = () => {
        let tileSize = 500;
        let targetMedianValue = 0.5;
        let averageValues = [];
        let standardDeviationValues = [];
        let medianAverageAbsoluteDifferenceValues = [];
        let poissonIndexValues = [];

        let startX = this.windowSize;
        let endX = this.image.width - this.windowSize;
        let startY = this.windowSize;
        let endY = this.image.height - this.windowSize;

        for (var x = startX; x <= endX - tileSize; x += tileSize) {
            for (var y = startY; y <= endY - tileSize; y += tileSize) {
                calculateFilterValues(x, y);
                averageValues.push(filterAverageValue);
                standardDeviationValues.push(filterStandardDeviationValue);
                medianAverageAbsoluteDifferenceValues.push(filterMedianAverageAbsoluteDifferenceValue);
                poissonIndexValues.push(filterPoissonIndexValue);
            }
        }

        let indices = averageValues.map((_, index) => index);
        indices = indices.sort(function(a, b) { return averageValues[a] - averageValues[b]; });

        averageValues = reorderArray(averageValues, indices).slice(0, Math.floor(averageValues.length / 4));
        standardDeviationValues = reorderArray(standardDeviationValues, indices).slice(0, Math.floor(standardDeviationValues.length / 4));
        medianAverageAbsoluteDifferenceValues = reorderArray(medianAverageAbsoluteDifferenceValues, indices).slice(0, Math.floor(medianAverageAbsoluteDifferenceValues.length / 4));
        poissonIndexValues = reorderArray(poissonIndexValues, indices).slice(0, Math.floor(poissonIndexValues.length / 4));

        let medianAverageScore = 1 / averageValues[Math.floor(averageValues.length / 2)];
        let medianStandardDeviationScore = 1 / standardDeviationValues[Math.floor(standardDeviationValues.length / 2)];
        let medianMedianAverageAbsoluteDifferenceScore = 1 / medianAverageAbsoluteDifferenceValues[Math.floor(medianAverageAbsoluteDifferenceValues.length / 2)];
        let medianPoissonIndexScore = 1 / poissonIndexValues[Math.floor(poissonIndexValues.length / 2)];

        filterStandardDeviationNormalization = (targetMedianValue * filterStandardDeviationCap * medianAverageScore) / medianStandardDeviationScore;
        filterMedianAverageAbsoluteDifferenceNormalization = (targetMedianValue * filterMedianAverageAbsoluteDifferenceCap * medianAverageScore) / medianMedianAverageAbsoluteDifferenceScore;
        filterPoissonIndexNormalization = (targetMedianValue * filterPoissonIndexCap * medianAverageScore) / medianPoissonIndexScore;
    }

    let reorderArray = (array, indices) => {
        let newArray = new Array(array.length);
        for (var i = 0; i < array.length; i++) {
            newArray[i] = array[indices[i]];
        }
        return newArray;
    }

    let calculateAverage = (x, y) => {
        let average = 0;
        for (let dx = 0; dx < this.windowSize; dx++) {
            for (let dy = 0; dy < this.windowSize; dy++) {
                for (var c = 0; c < this.image.numberOfChannels; c++) {
                    average += this.image.sample(x + dx, y + dy, c);
                }
            }
        }
        filterAverageValue = average / (this.windowSize * this.windowSize * this.image.numberOfChannels);
        if (isNaN(filterAverageValue) || !isFinite(filterAverageValue)) {
            console.writeln("Invalid filterAverageValue: " + filterAverageValue);
        }
    }

    let calculateStandardDeviation = (x, y, average) => {
        let standardDeviation = 0;
        let pixelBrightness = 0;
        for (var dx = 0; dx < this.windowSize; dx++) {
            for (var dy = 0; dy < this.windowSize; dy++) {
                pixelBrightness = 0;
                for (var c = 0; c < this.image.numberOfChannels; c++) {
                    pixelBrightness += this.image.sample(x + dx, y + dy, c);
                }
                standardDeviation += Math.pow(pixelBrightness - average, 2);
            }
        }
        filterStandardDeviationValue = Math.sqrt(standardDeviation / (this.windowSize * this.windowSize * this.image.numberOfChannels));
        if (isNaN(filterStandardDeviationValue) || !isFinite(filterStandardDeviationValue)) {
            console.writeln("Invalid filterStandardDeviationValue: " + filterStandardDeviationValue);
        }
    }

    let calculateMedianAverageAbsoluteDifference = (x, y, average, stDev) => {
        for (var dx = 0; dx < this.windowSize; dx++) {
            for (var dy = 0; dy < this.windowSize; dy++) {
                let pixelBrightness = 0;
                for (var c = 0; c < this.image.numberOfChannels; c++) {
                    pixelBrightness += this.image.sample(x + dx, y + dy, c);
                }
                this.brightnessArray[dx * this.windowSize + dy] = pixelBrightness;
            }
        }
        this.brightnessArray = this.brightnessArray.sort((a, b) => a - b);
        let index = Math.floor(this.brightnessArray.length / 2);
        if (this.brightnessArray.length % 2) {
            filterMedianAverageAbsoluteDifferenceValue = Math.abs(this.brightnessArray[index] - average) / stDev;
        } else {
            filterMedianAverageAbsoluteDifferenceValue = Math.abs((this.brightnessArray[index - 1] + this.brightnessArray[index]) / 2 - average) / stDev;
        }
        if (isNaN(filterMedianAverageAbsoluteDifferenceValue) || !isFinite(filterMedianAverageAbsoluteDifferenceValue)) {
            console.writeln("Invalid filterMedianAverageAbsoluteDifferenceValue: " + filterMedianAverageAbsoluteDifferenceValue);
        }
    }

    let calculatePoissonIndex = (x, y) => {
        let averages = new Array(this.image.numberOfChannels);
        for (var i = 0; i < averages.length; i++) {
            averages[i] = 0;
        }
        for (var dx = 0; dx < this.windowSize; dx++) {
            for (var dy = 0; dy < this.windowSize; dy++) {
                for (var c = 0; c < this.image.numberOfChannels; c++) {
                    averages[c] += this.image.sample(x + dx, y + dy, c);
                }
            }
        }
        for (var i = 0; i < averages.length; i++) {
            averages[i] /= this.windowSize * this.windowSize;
        }
        let variances = new Array(this.image.numberOfChannels);
        for (var i = 0; i < variances.length; i++) {
            variances[i] = 0;
        }
        for (var dx = 0; dx < this.windowSize; dx++) {
            for (var dy = 0; dy < this.windowSize; dy++) {
                for (var c = 0; c < this.image.numberOfChannels; c++) {
                    variances[c] += Math.pow(this.image.sample(x + dx, y + dy, c) - averages[c], 2);
                }
            }
        }
        for (var i = 0; i < variances.length; i++) {
            variances[i] /= this.windowSize * this.windowSize;
        }
        let poissonIndexes = new Array(this.image.numberOfChannels);
        for (var i = 0; i < poissonIndexes.length; i++) {
            poissonIndexes[i] = Math.abs(averages[i] - variances[i]) / averages[i];
        }
        let poissonIndex = 0;
        for (var i = 0; i < poissonIndexes.length; i++) {
            poissonIndex += poissonIndexes[i];
        }
        filterPoissonIndexValue = Math.abs(poissonIndex / this.image.numberOfChannels - 1);
        if (isNaN(filterPoissonIndexValue) || !isFinite(filterPoissonIndexValue)) {
            console.writeln("Invalid filterPoissonIndexValue: " + filterPoissonIndexValue);
        }
    }
}

// =====================================================================
// FINDBACKGROUND PREVIEW / CUSTOM REGION UI HELPERS
// =====================================================================

function TAPFB_configurePixelMath( P )
{
   P.clearImageCacheAndExit = false;
   P.cacheGeneratedImages = false;
   P.generateOutput = true;
   P.singleThreaded = false;
   P.optimization = true;
   P.use64BitWorkingImage = false;
   P.rescale = false;
   P.rescaleLower = 0;
   P.rescaleUpper = 1;
   P.truncate = true;
   P.truncateLower = 0;
   P.truncateUpper = 1;
   P.createNewImage = false;
   P.showNewImage = true;
}

function TAPFB_processMonoImage( targetView, targetMedian )
{
   var P = new ProcessContainer;
   var P001 = new PixelMath;
   P001.expression =
      "BlackPoint = iif((med($T) - 2.7*sdev($T))<min($T),min($T),med($T) - 2.7*sdev($T));\n" +
      "Rescaled = ($T - BlackPoint) / (1 - BlackPoint);";
   P001.useSingleExpression = true;
   P001.symbols = "BlackPoint, Rescaled, CurrentMedian, DesiredMedian, Alpha";
   TAPFB_configurePixelMath( P001 );
   P.add( P001 );

   var P002 = new PixelMath;
   P002.expression =
      "((Med($T)-1)*" + targetMedian + "*$T)/(Med($T)*(" + targetMedian + "+$T-1)-" + targetMedian + "*$T)";
   P002.useSingleExpression = true;
   P002.symbols = "L, S";
   TAPFB_configurePixelMath( P002 );
   P.add( P002 );
   P.executeOn( targetView );
}

function TAPFB_processLinkedColorImage( targetView, targetBackground )
{
   /*
    * Nonlinear RGB-linked stretch used only for the temporary Custom
    * FindBackground display image. The real *_work image remains linear.
    */
   if ( !targetView.image.isColor || targetView.image.numberOfNominalChannels < 3 )
      return;

   var shadowsClipping = -1.25;
   var median = targetView.computeOrFetchProperty( "Median" );
   var mad = targetView.computeOrFetchProperty( "MAD" );

   if ( median == null || mad == null )
      throw new Error(
         "FindBackground preview: could not obtain Median/MAD statistics."
      );

   mad.mul( 1.4826 );

   var med = ( median.at( 0 ) + median.at( 1 ) + median.at( 2 ) ) / 3.0;
   var dev = ( mad.at( 0 ) + mad.at( 1 ) + mad.at( 2 ) ) / 3.0;
   var c0 = 0.0;
   var c1 = 1.0;
   var m = 0.5;

   if ( med < 0.5 )
   {
      c0 = Math.range( med + shadowsClipping * dev, 0.0, 1.0 );
      m = Math.mtf( targetBackground, med - c0 );
   }
   else
   {
      c1 = Math.range( med - shadowsClipping * dev, 0.0, 1.0 );
      m = 1.0 - Math.mtf( targetBackground, c1 - med );
   }

   var H = new HistogramTransformation;
   H.H =
   [
      [ c0, m, c1, 0.0, 1.0 ],
      [ c0, m, c1, 0.0, 1.0 ],
      [ c0, m, c1, 0.0, 1.0 ],
      [ 0.0, 0.5, 1.0, 0.0, 1.0 ],
      [ 0.0, 0.5, 1.0, 0.0, 1.0 ]
   ];

   if ( !H.executeOn( targetView, false ) )
      throw new Error(
         "FindBackground preview: RGB Linked nonlinear stretch failed."
      );

   console.writeln(
      "FindBackground Custom preview: RGB Linked nonlinear stretch applied."
   );
   console.writeln(
      "Preview target background: " + targetBackground.toFixed( 2 )
   );
}

function TAPFB_makeDisplayImage( sourceImage, maxWidth, maxHeight )
{
   var w = new ImageWindow(
      sourceImage.width,
      sourceImage.height,
      sourceImage.numberOfChannels,
      sourceImage.bitsPerSample,
      sourceImage.isReal,
      sourceImage.isColor
   );

   w.hide();
   w.mainView.beginProcess( UndoFlag_NoSwapFile );
   w.mainView.image.assign( sourceImage );
   w.mainView.endProcess();

   if ( sourceImage.numberOfChannels == 1 )
      TAPFB_processMonoImage( w.mainView, 0.25 );
   else
      TAPFB_processLinkedColorImage( w.mainView, 0.25 );

   var factor = Math.ceil(
      Math.max(
         sourceImage.width / maxWidth,
         sourceImage.height / maxHeight,
         1
      )
   );
   factor = Math.max( 1, Math.min( factor, 8 ) );

   if ( factor > 1 )
   {
      var R = new IntegerResample;
      R.zoomFactor = -factor;
      R.executeOn( w.mainView );
   }

   var result = new Image( w.mainView.image );
   w.forceClose();

   return {
      image: result,
      factor: factor
   };
}

function TAPFB_ScrollControl_init( parent )
{

   this.autoScroll = true;
   this.tracking = true;
   this.displayImage = null;
   this.dragging = false;
   this.dragOrigin = new Point( 0, 0 );
   this.isSelecting = false;
   this.userDefinedRegions = [];
   this.currentRegion = null;
   this.startX = 0;
   this.startY = 0;
   this.scrollPosition = new Point( 0, 0 );

   this.viewport.cursor = new Cursor( StdCursor_Cross );

   this.doUpdateImage = function( image )
   {
      this.displayImage = image;
      this.initScrollBars();
      this.viewport.update();
   };

   this.initScrollBars = function()
   {
      var image = this.displayImage;
      if ( image == null || image.width <= 0 || image.height <= 0 )
      {
         this.setHorizontalScrollRange( 0, 0 );
         this.setVerticalScrollRange( 0, 0 );
      }
      else
      {
         this.setHorizontalScrollRange( 0, Math.max( 0, image.width - this.viewport.width ) );
         this.setVerticalScrollRange( 0, Math.max( 0, image.height - this.viewport.height ) );
      }
      this.viewport.update();
   };

   this.viewport.onResize = function()
   {
      if ( this.parent )
         this.parent.initScrollBars();
   };

   this.onHorizontalScrollPosUpdated = function( x )
   {
      this.scrollPosition.x = x;
      this.viewport.update();
   };

   this.onVerticalScrollPosUpdated = function( y )
   {
      this.scrollPosition.y = y;
      this.viewport.update();
   };

   this.viewport.onMousePress = function( x, y, button, buttons, modifiers )
   {
      var p = this.parent;
      if ( modifiers === 1 ) // Shift
      {
         p.startX = x + p.scrollPosition.x;
         p.startY = y + p.scrollPosition.y;
         p.isSelecting = true;
         p.dragging = false;
         p.currentRegion = null;
      }
      else
      {
         this.cursor = new Cursor( StdCursor_ClosedHand );
         p.dragOrigin.x = x;
         p.dragOrigin.y = y;
         p.dragging = true;
      }
   };

   this.viewport.onMouseMove = function( x, y, buttons, modifiers )
   {
      var p = this.parent;
      if ( !p ) return;

      if ( p.isSelecting )
      {
         var left = Math.min( p.startX, x + p.scrollPosition.x );
         var top = Math.min( p.startY, y + p.scrollPosition.y );
         var right = Math.max( p.startX, x + p.scrollPosition.x );
         var bottom = Math.max( p.startY, y + p.scrollPosition.y );

         if ( p.displayImage )
         {
            left = Math.max( 0, Math.min( left, p.displayImage.width ) );
            right = Math.max( 0, Math.min( right, p.displayImage.width ) );
            top = Math.max( 0, Math.min( top, p.displayImage.height ) );
            bottom = Math.max( 0, Math.min( bottom, p.displayImage.height ) );
         }

         p.currentRegion = new Rect( left, top, right, bottom );
         p.viewport.update();
      }
      else if ( p.dragging )
      {
         p.scrollPosition = new Point( p.scrollPosition ).translatedBy(
            p.dragOrigin.x - x,
            p.dragOrigin.y - y
         );
         p.dragOrigin.x = x;
         p.dragOrigin.y = y;
         p.viewport.update();
      }
   };

   this.viewport.onMouseRelease = function( x, y, button, buttons, modifiers )
   {
      var p = this.parent;
      if ( !p ) return;

      if ( p.isSelecting )
      {
         p.isSelecting = false;
         if ( p.currentRegion )
         {
            var r = p.currentRegion;
            if ( Math.abs( r.right - r.left ) >= 5 && Math.abs( r.bottom - r.top ) >= 5 )
               p.userDefinedRegions.push( r );
         }
         p.currentRegion = null;
         p.viewport.update();
      }
      else
      {
         this.cursor = new Cursor( StdCursor_Cross );
         p.dragging = false;
      }
   };

   this.viewport.onPaint = function( x0, y0, x1, y1 )
   {
      var g = new Graphics( this );
      var image = this.parent.displayImage;

      if ( image == null )
      {
         g.fillRect( x0, y0, x1, y1, new Brush( 0xff000000 ) );
      }
      else
      {
         image.selectedRect = new Rect( x0, y0, x1, y1 ).translated( this.parent.scrollPosition );
         g.drawBitmap( x0, y0, image.render() );
         image.resetRectSelection();

         g.pen = new Pen( 0xff00ff00 );
         for ( var i = 0; i < this.parent.userDefinedRegions.length; ++i )
         {
            var r = this.parent.userDefinedRegions[i];
            g.drawRect( r.translatedBy( -this.parent.scrollPosition.x, -this.parent.scrollPosition.y ) );
         }

         if ( this.parent.currentRegion )
         {
            g.pen = new Pen( 0xffffff00 );
            g.drawRect( this.parent.currentRegion.translatedBy(
               -this.parent.scrollPosition.x,
               -this.parent.scrollPosition.y
            ) );
         }
      }
      g.end();
   };
}

var TAPFB_ScrollControl = class extends ScrollBox
{
   constructor( parent )
   {
      super( parent );
      TAPFB_ScrollControl_init.call( this, parent );
   }
};

function TAPFB_CustomDialog_init( targetView )
{
   var dialog = this;

   this.title_Label = new Label( this );
   this.title_Label.useRichText = true;
   this.title_Label.wordWrapping = true;
   this.title_Label.text =
      "<b>Find Background - Custom Search Area</b><br/>" +
      "Hold <b>Shift</b>, click and drag to define one or more search areas. " +
      "Green rectangles are the regions FindBackground will search.";

   this.previewControl = new TAPFB_ScrollControl( this );
   this.previewControl.setMinWidth( 820 );
   this.previewControl.setMinHeight( 520 );

   var display = TAPFB_makeDisplayImage( targetView.image, 820, 520 );
   this.downsamplingFactor = display.factor;
   this.previewControl.doUpdateImage( display.image );

   this.info_Label = new Label( this );
   this.info_Label.text = "Target: " + targetView.id + "  |  Preview scale: 1:" + this.downsamplingFactor;

   this.reset_Button = new PushButton( this );
   this.reset_Button.text = "Reset Selection";
   this.reset_Button.onClick = function()
   {
      dialog.previewControl.userDefinedRegions = [];
      dialog.previewControl.currentRegion = null;
      dialog.previewControl.viewport.update();
   };

   this.search_Button = new PushButton( this );
   this.search_Button.text = "Search";
   this.search_Button.defaultButton = true;
   this.search_Button.onClick = function()
   {
      if ( dialog.previewControl.userDefinedRegions.length == 0 )
      {
         ( new MessageBox(
            "Define at least one region with Shift + click and drag before starting the search.",
            "Find Background - Custom",
            StdIcon_Error,
            StdButton_Ok
         ) ).execute();
         return;
      }
      dialog.ok();
   };

   this.cancel_Button = new PushButton( this );
   this.cancel_Button.text = "Cancel";
   this.cancel_Button.onClick = function() { dialog.cancel(); };

   var buttons = new HorizontalSizer;
   buttons.spacing = 8;
   buttons.add( this.reset_Button );
   buttons.addStretch();
   buttons.add( this.search_Button );
   buttons.add( this.cancel_Button );

   this.sizer = new VerticalSizer;
   this.sizer.margin = 10;
   this.sizer.spacing = 8;
   this.sizer.add( this.title_Label );
   this.sizer.add( this.info_Label );
   this.sizer.add( this.previewControl, 100 );
   this.sizer.add( buttons );

   this.windowTitle = "Find Background - Custom Search Area";
   this.adjustToContents();

   this.getScaledRegions = function()
   {
      var f = dialog.downsamplingFactor || 1;
      var regions = [];
      for ( var i = 0; i < dialog.previewControl.userDefinedRegions.length; ++i )
      {
         var r = dialog.previewControl.userDefinedRegions[i];
         regions.push( new Rect(
            Math.round( r.left * f ),
            Math.round( r.top * f ),
            Math.round( r.right * f ),
            Math.round( r.bottom * f )
         ) );
      }
      return regions;
   };
}

var TAPFB_CustomDialog = class extends Dialog
{
   constructor( targetView )
   {
      super();
      TAPFB_CustomDialog_init.call( this, targetView );
   }
};

function TAPFB_deletePreviewById( window, id )
{
   try
   {
      var previews = window.previews;
      for ( var i = previews.length - 1; i >= 0; --i )
         if ( previews[i].id == id )
            window.deletePreview( previews[i] );
   }
   catch ( e )
   {
      console.warningln( "Could not remove previous FindBackground preview: " + e.message );
   }
}

function executeFindBackground( view, customMode )
{
   logStep( "[7] Find and Neutralize Background - Find Background" );
   view.window.bringToFront();
   CoreApplication.processEvents();

   var regions = [];
   if ( customMode )
   {
      console.writeln( "Mode: Custom Search Area" );
      var customDialog = new TAPFB_CustomDialog( view );
      if ( !customDialog.execute() )
      {
         console.noteln( "Find Background Custom mode cancelled by user. Step skipped." );
         return { success: false, rect: null };
      }
      regions = customDialog.getScaledRegions();
      if ( regions.length == 0 )
      {
         console.noteln( "No Custom FindBackground regions were defined. Step skipped." );
         return { success: false, rect: null };
      }
   }
   else
   {
      console.writeln( "Mode: Full Image" );
   }

   TAPFB_deletePreviewById( view.window, "Background" );

   console.writeln( "Search routine             : Fast" );
   console.writeln( "Size                       : 50" );
   console.writeln( "Spacing rate               : 2" );
   console.writeln( "Search grid width          : 100" );
   console.writeln( "Number of starting points  : 40" );
   console.writeln( "Standard deviation filter  : ON" );
   console.writeln( "Preview name               : Background" );

   var finder;
   if ( customMode )
      finder = new FindBackgroundUserDefined( 50, 2, regions );
   else
      finder = new FindBackground( 50, 2 );

   finder.filterAverage = true;
   finder.filterStandardDeviation = true;
   finder.filterMedianAverageAbsoluteDifference = false;
   finder.filterPoissonIndex = false;
   finder.filterForObjects = false;
   finder.generatePreview = true;
   finder.setTarget( view.window );

   var prevMaskEnabled = view.maskEnabled;
   var wrapped = false;
   try
   {
      view.maskEnabled = false;
      view.beginProcess( UndoFlag_NoSwapFile );
      wrapped = true;

      if ( customMode )
         finder.fastSearchBackgroundUserDefined( 100, 40, true, "Background" );
      else
         finder.fastSearchBackground( 100, 40, true, "Background" );
   }
   finally
   {
      view.maskEnabled = prevMaskEnabled;
      if ( wrapped )
         view.endProcess();
   }

   var resultRect = finder.lastResult || null;

   console.noteln( "Background Found! Preview 'Background' created on " + view.id + "." );
   if ( resultRect )
      console.writeln(
         "Background ROI             : [" +
         Math.round( resultRect.left ) + ", " +
         Math.round( resultRect.top ) + "] -> [" +
         Math.round( resultRect.right ) + ", " +
         Math.round( resultRect.bottom ) + "]"
      );

   CoreApplication.processEvents();
   return { success: true, rect: resultRect };
}


// =====================================================================
// 7.1 BACKGROUND NEUTRALIZATION FROM FINDBACKGROUND PREVIEW
// =====================================================================

function TAP_previewExists( window, id )
{
   try
   {
      var previews = window.previews;
      for ( var i = 0; i < previews.length; ++i )
         if ( previews[i].id == id )
            return true;
   }
   catch ( e )
   {
   }
   return false;
}

function executeBackgroundNeutralizationFromBackground( view, backgroundRect )
{
   logStep( "[7] Find and Neutralize Background - Background Neutralization" );

   if ( !backgroundRect )
      throw new Error(
         "BackgroundNeutralization requires the Background region returned by FindBackground."
      );

   if ( !TAP_previewExists( view.window, "Background" ) )
      throw new Error(
         "BackgroundNeutralization requires the preview 'Background', but it was not found on " +
         view.id + "."
      );

   var x0 = Math.max( 0, Math.round( backgroundRect.left ) );
   var y0 = Math.max( 0, Math.round( backgroundRect.top ) );
   var x1 = Math.min( view.image.width, Math.round( backgroundRect.right ) );
   var y1 = Math.min( view.image.height, Math.round( backgroundRect.bottom ) );

   if ( x1 <= x0 || y1 <= y0 )
      throw new Error(
         "BackgroundNeutralization received an invalid Background ROI."
      );

   var P = new BackgroundNeutralization;

   /*
    * Explicitly use the current *_work image as the reference image and
    * reproduce From Preview -> Background by assigning the same ROI that
    * FindBackground used to create the Background preview.
    */
   P.backgroundReferenceViewId = view.id;
   P.backgroundLow = 0.0000000;
   P.backgroundHigh = 0.1000000;
   P.useROI = true;
   P.roiX0 = x0;
   P.roiY0 = y0;
   P.roiX1 = x1;
   P.roiY1 = y1;
   P.mode = BackgroundNeutralization.RescaleAsNeeded;
   P.targetBackground = 0.0010000;

   console.writeln( "Reference Image : " + view.id );
   console.writeln( "Region of Interest: ON" );
   console.writeln( "From Preview    : " + view.id + "->Background" );
   console.writeln( "ROI             : [" + x0 + ", " + y0 + "] -> [" + x1 + ", " + y1 + "]" );
   console.writeln( "Lower limit     : 0.000000" );
   console.writeln( "Upper limit     : 0.100000" );
   console.writeln( "Working mode    : Rescale as needed" );

   view.window.bringToFront();

   if ( !P.executeOn( view ) )
      throw new Error( "BackgroundNeutralization failed." );

   console.noteln( "BackgroundNeutralization completed." );

   TAPFB_deletePreviewById( view.window, "Background" );
   console.noteln( "Preview 'Background' deleted after BackgroundNeutralization." );

   CoreApplication.processEvents();
}


// =====================================================================
// 8. SETIASTRO NB TO RGB STAR COMBINATION / STAR STRETCH
// =====================================================================

/*
 * Adapted from SetiAstro NB to RGB Stars Script v1.6.
 * Original author: Franklin Marek / SetiAstro
 * Copyright (c) 2024 Franklin Marek
 * Original license: CC BY-NC 4.0
 * https://creativecommons.org/licenses/by-nc/4.0/
 *
 * The original script accepts an OSC dual-band star image, extracts its
 * red and green channels as Ha/OIII, combines them into a natural-looking
 * RGB star image, performs SCNR/tone normalization, and optionally applies
 * the nonlinear Star Stretch plus ColorSaturation. This workflow adaptation
 * always enables Green Channel Blend Ratio, Apply Star Stretch and visual
 * output, and exposes Ha/OIII ratio, Stretch Factor and Color Boost in the
 * AstroTemps AutoProcessing Tool interface.
 */

function TAPSTAR_getAllImageIDs()
{
   var windows = ImageWindow.windows;
   var ids = [];
   for ( var i = 0; i < windows.length; ++i )
      ids.push( windows[i].mainView.id );
   return ids;
}

function TAPSTAR_findNewImageID( oldIDs, newIDs )
{
   for ( var i = 0; i < newIDs.length; ++i )
   {
      var found = false;
      for ( var j = 0; j < oldIDs.length; ++j )
      {
         if ( newIDs[i] == oldIDs[j] )
         {
            found = true;
            break;
         }
      }
      if ( !found )
         return newIDs[i];
   }
   return null;
}

function TAPSTAR_getWindowById( id )
{
   try
   {
      var w = ImageWindow.windowById( id );
      if ( w == null )
         return null;
      if ( typeof w.isNull != "undefined" && w.isNull )
         return null;
      return w;
   }
   catch ( e )
   {
      return null;
   }
}

function TAPSTAR_extractChannel( sourceView, channelIndex, suffix, extractedChannels )
{
   var oldIDs = TAPSTAR_getAllImageIDs();

   var P = new ChannelExtraction;
   P.colorSpace = ChannelExtraction.RGB;
   P.channels =
   [
      [ channelIndex === 0, "" ],
      [ channelIndex === 1, "" ],
      [ channelIndex === 2, "" ]
   ];
   P.sampleFormat = ChannelExtraction.SameAsSource;
   P.inheritAstrometricSolution = true;

   if ( !P.executeOn( sourceView ) )
      throw new Error(
         "NB to RGB Stars: ChannelExtraction failed for channel " + channelIndex + "."
      );

   var newID = TAPSTAR_findNewImageID( oldIDs, TAPSTAR_getAllImageIDs() );
   if ( newID == null )
      throw new Error(
         "NB to RGB Stars: could not identify the extracted channel image."
      );

   var extractedWindow = TAPSTAR_getWindowById( newID );
   if ( extractedWindow == null )
      throw new Error(
         "NB to RGB Stars: extracted channel window is not available."
      );

   var desiredId = uniqueImageId( sourceView.id + suffix );
   extractedWindow.mainView.id = desiredId;
   extractedChannels.push( desiredId );
   extractedWindow.hide();

   return extractedWindow.mainView;
}

function TAPSTAR_closeExtractedChannels( extractedChannels )
{
   for ( var i = 0; i < extractedChannels.length; ++i )
   {
      var w = TAPSTAR_getWindowById( extractedChannels[i] );
      if ( w != null )
      {
         try
         {
            w.forceClose();
         }
         catch ( e )
         {
         }
      }
   }
}

function TAPSTAR_combineNBtoRGB( haView, oiiiView, haToOiiiRatio, outputId, showOutput )
{
   var oldIDs = TAPSTAR_getAllImageIDs();

   var ratio = clampValue( haToOiiiRatio, 0.0, 1.0 );

   var P = new PixelMath;
   P.expression =
      "0.5*" + haView.id + " + 0.5*" + haView.id;
   P.expression1 =
      ratio + "*" + haView.id + " + ~" + ratio + "*" + oiiiView.id;
   P.expression2 = oiiiView.id;
   P.expression3 = "";
   P.useSingleExpression = false;
   P.symbols = "";
   P.clearImageCacheAndExit = false;
   P.cacheGeneratedImages = false;
   P.generateOutput = true;
   P.singleThreaded = false;
   P.optimization = true;
   P.use64BitWorkingImage = false;
   P.rescale = false;
   P.rescaleLower = 0;
   P.rescaleUpper = 1;
   P.truncate = true;
   P.truncateLower = 0;
   P.truncateUpper = 1;
   P.createNewImage = true;
   P.showNewImage = true;
   P.newImageId = outputId || "NBtoRGB_stars";
   P.showNewImage = showOutput !== false;
   P.newImageWidth = 0;
   P.newImageHeight = 0;
   P.newImageAlpha = false;
   P.newImageColorSpace = PixelMath.RGB;
   P.newImageSampleFormat = PixelMath.SameAsTarget;

   if ( !P.executeOn( haView ) )
      throw new Error( "NB to RGB Stars: PixelMath RGB combination failed." );

   var newID = TAPSTAR_findNewImageID( oldIDs, TAPSTAR_getAllImageIDs() );
   if ( newID == null )
      throw new Error(
         "NB to RGB Stars: could not identify the combined RGB star image."
      );

   var resultWindow = TAPSTAR_getWindowById( newID );
   if ( resultWindow == null )
      throw new Error(
         "NB to RGB Stars: combined RGB star image window is not available."
      );

   return resultWindow.mainView;
}

function TAPSTAR_applySCNR( view )
{
   var P = new SCNR;
   P.amount = 1.00;
   P.protectionMethod = SCNR.AverageNeutral;
   P.colorToRemove = SCNR.Green;
   P.preserveLightness = true;
   if ( !P.executeOn( view ) )
      throw new Error( "NB to RGB Stars: SCNR failed." );
}

function TAPSTAR_applyMTF( view )
{
   var P = new PixelMath;
   P.expression = "mtf(0.01, $T)";
   P.useSingleExpression = true;
   if ( !P.executeOn( view ) )
      throw new Error( "NB to RGB Stars: initial MTF failed." );
}

function TAPSTAR_reverseMTF( view )
{
   var P = new PixelMath;
   P.expression = "mtf(~0.01, $T)";
   P.useSingleExpression = true;
   if ( !P.executeOn( view ) )
      throw new Error( "NB to RGB Stars: reverse MTF failed." );
}

function TAPSTAR_applyStarStretch( view, stretchFactor, colorBoost )
{
   stretchFactor = clampValue( stretchFactor, 0.0, 8.0 );
   colorBoost = clampValue( colorBoost, 0.0, 3.0 );

   var P = new PixelMath;
   P.expression =
      "((3^" + stretchFactor + ")*$T)/((3^" + stretchFactor + "-1)*$T+1)";
   P.useSingleExpression = true;
   if ( !P.executeOn( view ) )
      throw new Error( "NB to RGB Stars: nonlinear Star Stretch failed." );

   var C = new ColorSaturation;
   C.HS =
   [
      [ 0.00000, colorBoost * 0.40000 ],
      [ 0.50000, colorBoost * 0.70000 ],
      [ 1.00000, colorBoost * 0.40000 ]
   ];
   C.HSt = ColorSaturation.AkimaSubsplines;
   C.hueShift = 0.000;

   if ( !C.executeOn( view ) )
      throw new Error( "NB to RGB Stars: Color Boost failed." );
}


function TAPSTAR_cloneView( sourceView, outputId, showWindow )
{
   if ( sourceView == null || sourceView.isNull || sourceView.image == null )
      throw new Error( "Star Stretch: invalid stars-only source image." );

   var src = sourceView.image;
   var id = uniqueImageId( outputId || "NBtoRGB_stars" );

   var w = new ImageWindow(
      src.width, src.height,
      src.numberOfChannels,
      src.bitsPerSample,
      src.isReal,
      src.isColor,
      id
   );

   w.mainView.beginProcess( UndoFlag_NoSwapFile );
   w.mainView.image.assign( src );
   w.mainView.endProcess();

   if ( showWindow !== false )
      w.show();
   else
      w.hide();

   return w.mainView;
}

function TAPSTAR_processSetiStarStretch( starsView, stretchAmount, colorBoost, removeGreen, outputId, showOutput )
{
   var result = TAPSTAR_cloneView(
      starsView, outputId || "NBtoRGB_stars", showOutput !== false );

   if ( removeGreen )
      TAPSTAR_applySCNR( result );

   TAPSTAR_applyStarStretch(
      result,
      clampValue( stretchAmount, 0.0, 8.0 ),
      clampValue( colorBoost, 0.0, 3.0 )
   );

   if ( showOutput !== false )
   {
      result.window.show();
      result.window.bringToFront();
      result.window.zoomToOptimalFit();
   }

   CoreApplication.processEvents();
   return result;
}

function TAPSTAR_makeReducedPreviewSource( sourceView, factor, id )
{
   var preview = TAPSTAR_cloneView( sourceView, id, false );
   factor = Math.max( 1, Math.round( factor ) );

   if ( factor > 1 )
   {
      var R = new IntegerResample;
      R.zoomFactor = -factor;
      if ( !R.executeOn( preview ) )
      {
         try { preview.window.forceClose(); } catch ( e0 ) {}
         throw new Error( "Star Stretch preview resampling failed." );
      }
   }

   return preview;
}

function TAPSTAR_closeViewQuietly( view )
{
   try
   {
      if ( view != null && !view.isNull && view.window != null && !view.window.isNull )
         view.window.forceClose();
   }
   catch ( e ) {}
}

function TAPSTAR_previewZoomFactorFromIndex( index )
{
   switch ( index )
   {
   case 0: return 1;
   case 1: return 2;
   case 2: return 4;
   case 3: return 8;
   default: return 4;
   }
}

function TAPSTAR_previewZoomIndexFromFactor( factor )
{
   factor = Math.round( Number( factor ) );
   return factor == 1 ? 0 : factor == 2 ? 1 : factor == 8 ? 3 : 2;
}

function TAPSTAR_NBtoRGBDialog_init( starsView, s )
{
   var self = this;
   this.windowTitle = "SetiAstro's NB to RGB Stars - FT-Astro";
   this.applied = false;
   this.skipped = false;
   this.resultView = null;
   this.previewInput = null;
   this.previewResult = null;

   var title = new Label( this );
   title.useRichText = true;
   title.textAlignment = TextAlign_HorzCenter | TextAlign_VertCenter;
   title.text = "<b>SetiAstro's NB to RGB Stars</b>";

   var info = new Label( this );
   info.useRichText = true;
   info.wordWrapping = true;
   info.text =
      "OSC dual-band stars-only image: <b>" + starsView.id + "</b><br/>" +
      "Adjust the Ha/OIII balance and SetiAstro star stretch visually. " +
      "The preview is temporary; <b>Execute & Continue</b> creates NBtoRGB_stars and resumes the workflow.";

   this.ratio = new NumericControl( this );
   this.ratio.label.text = "Ha to OIII ratio:";
   this.ratio.setRange( 0.0, 1.0 );
   this.ratio.slider.setRange( 0, 1000 );
   this.ratio.setPrecision( 2 );
   this.ratio.setValue( s.starHaToOiiiRatio );

   this.stretch = new NumericControl( this );
   this.stretch.label.text = "Stretch Amount:";
   this.stretch.setRange( 0.0, 8.0 );
   this.stretch.slider.setRange( 0, 800 );
   this.stretch.setPrecision( 2 );
   this.stretch.setValue( s.starStretchFactor );

   this.color = new NumericControl( this );
   this.color.label.text = "Color Boost Amount:";
   this.color.setRange( 0.0, 3.0 );
   this.color.slider.setRange( 0, 300 );
   this.color.setPrecision( 2 );
   this.color.setValue( s.starColorBoost );

   this.showPreview = new CheckBox( this );
   this.showPreview.text = "Show Preview";
   this.showPreview.checked = true;

   var zoomLabel = new Label( this );
   zoomLabel.text = "Zoom:";
   this.zoom = new ComboBox( this );
   this.zoom.addItem( "1:1" );
   this.zoom.addItem( "1:2" );
   this.zoom.addItem( "1:4" );
   this.zoom.addItem( "1:8" );
   this.zoom.currentItem = TAPSTAR_previewZoomIndexFromFactor( s.starStretchPreviewZoom );

   this.refresh = new PushButton( this );
   this.refresh.text = "Refresh Preview";

   this.executeButton = new PushButton( this );
   this.executeButton.text = "Execute && Continue";

   this.cancelButton = new PushButton( this );
   this.cancelButton.text = "Cancel Workflow";

   this.skipButton = new PushButton( this );
   this.skipButton.text = "Skip Star Stretch";
   this.skipButton.toolTip = "<p>Continue the workflow without stretching/rebuilding the stars.</p>";

   this.closePreview = function()
   {
      TAPSTAR_closeViewQuietly( self.previewResult );
      TAPSTAR_closeViewQuietly( self.previewInput );
      self.previewResult = null;
      self.previewInput = null;
   };

   this.refreshPreview = function()
   {
      self.closePreview();
      if ( !self.showPreview.checked )
         return;

      try
      {
         var factor = TAPSTAR_previewZoomFactorFromIndex( self.zoom.currentItem );
         self.previewInput = TAPSTAR_makeReducedPreviewSource(
            starsView, factor, "AstroTemps_NBtoRGB_preview_src" );

         var extracted = [];
         try
         {
            var ha = TAPSTAR_extractChannel( self.previewInput, 0, "_HaPreview", extracted );
            var oi = TAPSTAR_extractChannel( self.previewInput, 1, "_OIIIPreview", extracted );
            self.previewResult = TAPSTAR_combineNBtoRGB(
               ha, oi, self.ratio.value,
               uniqueImageId( "AstroTemps_NBtoRGB_Preview" ), true );

            TAPSTAR_applySCNR( self.previewResult );
            TAPSTAR_applyMTF( self.previewResult );
            TAPSTAR_applySCNR( self.previewResult );
            TAPSTAR_reverseMTF( self.previewResult );
            TAPSTAR_applyStarStretch(
               self.previewResult, self.stretch.value, self.color.value );

            TAPIC_placePreviewWindow( self.previewResult, self );
         }
         finally
         {
            TAPSTAR_closeExtractedChannels( extracted );
         }
      }
      catch ( e )
      {
         self.closePreview();
         new MessageBox(
            "Could not generate the Star Stretch preview.\n\n" + TAP_errorText( e ),
            "AstroTemps - Star Stretch Preview",
            StdIcon_Error, StdButton_Ok
         ).execute();
      }
   };

   this.refresh.onClick = function() { self.refreshPreview(); };
   this.showPreview.onCheck = function( checked )
   {
      if ( checked ) self.refreshPreview();
      else self.closePreview();
   };
   this.zoom.onItemSelected = function() { if ( self.showPreview.checked ) self.refreshPreview(); };

   this.executeButton.onClick = function()
   {
      self.closePreview();
      s.starHaToOiiiRatio = self.ratio.value;
      s.starStretchFactor = self.stretch.value;
      s.starColorBoost = self.color.value;
      s.starStretchPreviewZoom = TAPSTAR_previewZoomFactorFromIndex( self.zoom.currentItem );

      self.resultView = executeNBtoRGBStarStretch( starsView, s );
      self.applied = true;
      self.ok();
   };

   this.cancelButton.onClick = function()
   {
      self.closePreview();
      self.cancel();
   };

   this.skipButton.onClick = function()
   {
      self.closePreview();
      self.skipped = true;
      self.ok();
   };

   var zoomRow = new HorizontalSizer;
   zoomRow.spacing = 6;
   zoomRow.add( zoomLabel );
   zoomRow.add( this.zoom );
   zoomRow.add( this.refresh );
   zoomRow.addStretch();

   var buttons = new HorizontalSizer;
   buttons.spacing = 6;
   buttons.add( this.cancelButton );
   buttons.add( this.skipButton );
   buttons.addStretch();
   buttons.add( this.executeButton );

   this.sizer = new VerticalSizer;
   this.sizer.margin = 10;
   this.sizer.spacing = 7;
   this.sizer.add( title );
   this.sizer.add( info );
   this.sizer.add( this.ratio );
   this.sizer.add( this.stretch );
   this.sizer.add( this.color );
   this.sizer.add( this.showPreview );
   this.sizer.add( zoomRow );
   this.sizer.add( buttons );

   this.adjustToContents();
   this.setFixedWidth( Math.max( 660, this.width ) );

   CoreApplication.processEvents();
   this.refreshPreview();
}

