var TAPSTAR_SetiStarStretchDialog = class extends Dialog
{
   constructor( starsView, s )
   {
      super();
      TAPSTAR_SetiStarStretchDialog_init.call( this, starsView, s );
   }
};

function TAPSTAR_resolveStarsView( workView, idsBeforeStarX )
{
   if ( workView == null || workView.isNull )
      return null;

   if ( /_stars(?:_|$)/.test( workView.id ) )
      return workView;

   var baseId = workView.id.replace( /_work(?:_\d+)?$/, "" );
   var prefixes = [ workView.id + "_stars" ];
   if ( baseId != workView.id )
      prefixes.push( baseId + "_stars" );

   for ( var p = 0; p < prefixes.length; ++p )
   {
      var exactWindow = TAPSTAR_getWindowById( prefixes[p] );
      if ( exactWindow != null )
         return exactWindow.mainView;
   }

   var windows = ImageWindow.windows;

   // Prefer a newly generated star-layer image when we know the pre-removal IDs.
   if ( idsBeforeStarX )
   {
      for ( var i = 0; i < windows.length; ++i )
      {
         var id = windows[i].mainView.id;
         if ( idsBeforeStarX.indexOf( id ) < 0 )
            for ( p = 0; p < prefixes.length; ++p )
               if ( id.indexOf( prefixes[p] ) == 0 )
                  return windows[i].mainView;
      }
   }

   // Fallback: locate an existing star image associated with this work image.
   for ( var j = 0; j < windows.length; ++j )
   {
      var candidateId = windows[j].mainView.id;
      for ( p = 0; p < prefixes.length; ++p )
         if ( candidateId.indexOf( prefixes[p] ) == 0 )
            return windows[j].mainView;
   }

   return null;
}

function executeNBtoRGBStarStretch( starsView, s )
{
   logStep( "[12] Star Stretch" );

   if ( starsView == null || starsView.image == null )
      throw new Error(
         "Star Stretch requires a valid *_stars image. Enable Star Removal output (StarX > Output Stars or StarNet2 > Mask) or open an existing *_stars image."
      );

   if ( !starsView.image.isColor || starsView.image.numberOfNominalChannels < 3 )
      throw new Error(
         "NB to RGB Star Combination requires a color OSC *_stars image."
      );

   var ratio = clampValue( s.starHaToOiiiRatio, 0.0, 1.0 );
   var stretchFactor = clampValue( s.starStretchFactor, 0.0, 8.0 );
   var colorBoost = clampValue( s.starColorBoost, 0.0, 3.0 );

   console.writeln( "OSC (dual band) Image    : " + starsView.id );
   console.writeln( "Green Channel Blend      : ON" );
   console.writeln( "Ha to OIII ratio         : " + ratio.toFixed( 2 ) );
   console.writeln( "Apply Star Stretch       : ON" );
   console.writeln( "Stretch Factor           : " + stretchFactor.toFixed( 2 ) );
   console.writeln( "Color Boost              : " + colorBoost.toFixed( 2 ) );
   console.writeln( "Show Preview             : ON (processed result remains visible)" );

   var extractedChannels = [];
   var resultView = null;

   try
   {
      var haView = TAPSTAR_extractChannel( starsView, 0, "_Ha", extractedChannels );
      var oiiiView = TAPSTAR_extractChannel( starsView, 1, "_OIII", extractedChannels );

      resultView = TAPSTAR_combineNBtoRGB(
         haView, oiiiView, ratio, uniqueImageId( "NBtoRGB_stars" ), true );

      // Original SetiAstro adjustment sequence.
      TAPSTAR_applySCNR( resultView );
      TAPSTAR_applyMTF( resultView );
      TAPSTAR_applySCNR( resultView );
      TAPSTAR_reverseMTF( resultView );
      TAPSTAR_applyStarStretch( resultView, stretchFactor, colorBoost );
   }
   finally
   {
      TAPSTAR_closeExtractedChannels( extractedChannels );
   }

   if ( resultView == null )
      throw new Error( "NB to RGB Star Combination did not produce an output image." );

   resultView.window.show();
   resultView.window.bringToFront();
   resultView.window.zoomToOptimalFit();
   CoreApplication.processEvents();

   console.noteln( "NB to RGB Star Process Complete: " + resultView.id );
   return resultView;
}


