var TAPSS_Parameters =
{
   targetMedian: 0.23,
   curvesBoost: 0.15,
   normalizeImageRange: false,
   linkedStretch: true,
   blackpointSigma: 3.80,
   noBlackClip: false,
   hdrCompress: false,
   hdrAmount: 0.25,
   hdrKnee: 0.35,
   lumaOnly: false,
   lumaMode: "rec709",
   lumaBlend: 0.60
};

// ============================================================================
// Helpers / Core Utilities
// ============================================================================

function TAPSS_calculate_image_median(var_image) {
   return var_image.median();
}

function TAPSS_configurePixelMath(P, doTruncate) {
   P.clearImageCacheAndExit = false;
   P.cacheGeneratedImages = false;
   P.generateOutput = true;
   P.singleThreaded = false;
   P.optimization = true;
   P.use64BitWorkingImage = true;
   P.rescale = false;
   P.rescaleLower = 0;
   P.rescaleUpper = 1;

   // Only truncate when we explicitly want it (usually final step)
   P.truncate = (doTruncate === true);
   P.truncateLower = 0;
   P.truncateUpper = 1;

   P.createNewImage = false;
   P.showNewImage = true;
}

function TAPSS_disableSTF(targetView) {
   var stf = new ScreenTransferFunction;
   var stfParams = [
      [0.00000, 1.00000, 0.50000, 0.00000, 1.00000],
      [0.00000, 1.00000, 0.50000, 0.00000, 1.00000],
      [0.00000, 1.00000, 0.50000, 0.00000, 1.00000],
      [0.00000, 1.00000, 0.50000, 0.00000, 1.00000]
   ];
   stf.STF = stfParams;
   stf.executeOn(targetView, false);
   console.writeln("STF has been disabled.");
}

function TAPSS_lumaCoeffs() {
   switch ((TAPSS_Parameters.lumaMode || "rec709").toLowerCase()) {
      case "rec601":  return [0.2990, 0.5870, 0.1140];
      case "rec2020": return [0.2627, 0.6780, 0.0593];
      case "rec709":
      default:        return [0.2126, 0.7152, 0.0722];
   }
}

function TAPSS_hdrCompressExprMono(amount, knee) {
   return "" +
      "a = " + amount + ";\n" +
      "k = " + knee + ";\n" +
      // clamp knee to avoid div-by-zero and keep sane lower bound
      "k = min(0.999999, max(0.1, k));\n" +
      "x = $T;\n" +
      "hi = x > k;\n" +
      "t = (x - k)/(1 - k);\n" +
      "t = min(1, max(0, t));\n" +
      "t2 = t*t;\n" +
      "t3 = t2*t;\n" +
      "h10 = (t3 - 2*t2 + t);\n" +
      "h01 = (-2*t3 + 3*t2);\n" +
      "h11 = (t3 - t2);\n" +
      "m1 = min(5, max(1, 1 + 4*a));\n" +
      "f = h10*1 + h01*1 + h11*m1;\n" +
      "y = k + (1 - k)*min(1, max(0, f));\n" +
      "iif(hi, y, x);";
}

function TAPSS_hdrCompressExprColor(amount, knee) {
   var C = TAPSS_lumaCoeffs();              // uses TAPSS_Parameters.lumaMode
   var cr = C[0], cg = C[1], cb = C[2];

   return "" +
      "a = " + amount + ";\n" +
      "k = " + knee + ";\n" +
      "k = min(0.999999, max(0.1, k));\n" +
      "R = $T[0]; G = $T[1]; B = $T[2];\n" +
      "cr = " + cr + "; cg = " + cg + "; cb = " + cb + ";\n" +
      "Y = cr*R + cg*G + cb*B;\n" +
      "hi = Y > k;\n" +
      "t = (Y - k)/(1 - k);\n" +
      "t = min(1, max(0, t));\n" +
      "t2 = t*t;\n" +
      "t3 = t2*t;\n" +
      "h10 = (t3 - 2*t2 + t);\n" +
      "h01 = (-2*t3 + 3*t2);\n" +
      "h11 = (t3 - t2);\n" +
      "m1 = min(5, max(1, 1 + 4*a));\n" +
      "f = h10*1 + h01*1 + h11*m1;\n" +
      "Yc = k + (1 - k)*min(1, max(0, f));\n" +
      // ✅ CRITICAL: only scale above knee
      "s = iif(hi, iif(Y <= 1.0e-10, 1, Yc/Y), 1);\n" +
      "$T * s;";
}

function TAPSS_addHdrCompressProcess(container, isColor) {
   var H = new PixelMath;
   H.useSingleExpression = true;

   H.symbols = isColor
      ? "a,k,x,hi,t,t2,t3,h10,h01,h11,m1,f,y,R,G,B,cr,cg,cb,Y,Yc,s"
      : "a,k,x,hi,t,t2,t3,h10,h01,h11,m1,f,y";

   H.expression = isColor
      ? TAPSS_hdrCompressExprColor(TAPSS_Parameters.hdrAmount, TAPSS_Parameters.hdrKnee)
      : TAPSS_hdrCompressExprMono(TAPSS_Parameters.hdrAmount, TAPSS_Parameters.hdrKnee);

   TAPSS_configurePixelMath(H);
   container.add(H);
}
// ============================================================================
// Final curve boost (Bill Blanshan curve variant)
// ============================================================================

function TAPSS_applyFinalCurve(targetView, targetMedian) {
   let P = new CurvesTransformation();
   P.Bt = CurvesTransformation.AkimaSubsplines;

   P.K = [
      [0.00000, 0.00000],
      [0.5 * TAPSS_Parameters.targetMedian, 0.5 * TAPSS_Parameters.targetMedian],
      [TAPSS_Parameters.targetMedian, TAPSS_Parameters.targetMedian],
      [(1/4*(1-TAPSS_Parameters.targetMedian)+TAPSS_Parameters.targetMedian),
       Math.pow((1/4*(1-TAPSS_Parameters.targetMedian)+TAPSS_Parameters.targetMedian), (1-TAPSS_Parameters.curvesBoost))],
      [(3/4*(1-TAPSS_Parameters.targetMedian)+TAPSS_Parameters.targetMedian),
       Math.pow(Math.pow((3/4*(1-TAPSS_Parameters.targetMedian)+TAPSS_Parameters.targetMedian), (1-TAPSS_Parameters.curvesBoost)), (1-TAPSS_Parameters.curvesBoost))],
      [1.00000, 1.00000]
   ];

   P.St = CurvesTransformation.AkimaSubsplines;
   P.executeOn(targetView);
   console.noteln("Final Sigma Curves applied successfully after all iterations.");
}

// ============================================================================
// Clip estimator (Blackpoint Sigma step)
// ============================================================================

function TAPSS_imgStats(imgLive) {
   // Work on a clone so we never mutate the live view state
   var img = new Image(imgLive);

   var nchan = img.isColor ? 3 : 1;
   var median = new Array(nchan);
   var mad    = new Array(nchan);
   var minv   = new Array(nchan);

   var oldSel = img.selectedChannel;

   try {
      for (var c = 0; c < nchan; c++) {
         img.selectedChannel = c;
         median[c] = img.median();
         mad[c]    = img.MAD();
         minv[c]   = img.minimum();
      }
   } finally {
      // Restore on the clone (mostly irrelevant, but correct)
      img.selectedChannel = oldSel;
   }

   return { median: median, mad: mad, minimum: minv, isColor: img.isColor, nchan: nchan };
}

function TAPSS_computeBP_thresholds(img) {
   // Returns { mode:"mono"|"linked"|"lumaOnly"|"unlinked", bp: number or [bpR,bpG,bpB] }
   var st = TAPSS_imgStats(img);

   var sigma = 1.4826; // robust sigma from MAD
   var k = TAPSS_Parameters.blackpointSigma;
   var noClip = !!TAPSS_Parameters.noBlackClip;

   if (!img.isColor) {
      var Med = st.median[0];
      var Sig = sigma * st.mad[0];
      var BPraw = Med - k * Sig;
      var MinC = st.minimum[0];
      var BP = noClip ? MinC : (BPraw < MinC ? MinC : BPraw);
      return { mode: "mono", bp: BP };
   }

   // Color
   if (TAPSS_Parameters.linkedStretch || TAPSS_Parameters.lumaOnly) {
      // scalar BP based on chosen luma weights (matches your linked/luma-only Step 1)
      var C = TAPSS_lumaCoeffs();
      var cr = C[0], cg = C[1], cb = C[2];

      var Med = cr*st.median[0] + cg*st.median[1] + cb*st.median[2];
      var Sig = sigma * (cr*st.mad[0] + cg*st.mad[1] + cb*st.mad[2]);
      var MinC = Math.min(st.minimum[0], st.minimum[1], st.minimum[2]);
      var BPraw = Med - k * Sig;
      var BP = noClip ? MinC : (BPraw < MinC ? MinC : BPraw);

      return { mode: (TAPSS_Parameters.lumaOnly ? "lumaOnly" : "linked"), bp: BP };
   }

   // Unlinked: per-channel BP (matches your per-channel Step 1)
   var bp = [];
   for (var c = 0; c < 3; c++) {
      var Medc = st.median[c];
      var Sigc = sigma * st.mad[c];
      var BPrawc = Medc - k * Sigc;
      var Minc = st.minimum[c];
      var BPc = noClip ? Minc : (BPrawc < Minc ? Minc : BPrawc);
      bp.push(BPc);
   }
   return { mode: "unlinked", bp: bp };
}

function TAPSS_estimateClippedPixels_Blackpoint(img, maxSamples) {
   // Returns { clippedEst:int, total:int, sampled:int, stride:int, bpInfo:{...} }
   // Uses grid sampling when needed (estimate), exact when stride==1.

   maxSamples = maxSamples || 1000000; // ~1e6 samples max

   var w = img.width, h = img.height;
   var total = w * h;

   // Pick stride so sampled pixels <= maxSamples
   var stride = 1;
   if (total > maxSamples) {
      stride = Math.max(1, Math.floor(Math.sqrt(total / maxSamples)));
   }

   var bpInfo = TAPSS_computeBP_thresholds(img);
   var clipped = 0;
   var sampled = 0;

   if (!img.isColor) {
      var BP = bpInfo.bp;
      for (var y = 0; y < h; y += stride) {
         for (var x = 0; x < w; x += stride) {
            var v = img.sample(x, y);
            if (v < BP) clipped++;
            sampled++;
         }
      }
   } else {
      if (bpInfo.mode === "unlinked") {
         var bpr = bpInfo.bp[0], bpg = bpInfo.bp[1], bpb = bpInfo.bp[2];
         for (var y = 0; y < h; y += stride) {
            for (var x = 0; x < w; x += stride) {
               var r = img.sample(x, y, 0);
               var g = img.sample(x, y, 1);
               var b = img.sample(x, y, 2);
               if (r < bpr || g < bpg || b < bpb) clipped++;
               sampled++;
            }
         }
      } else {
         // scalar BP applied to all channels -> clip if any channel < BP
         var BPc = bpInfo.bp;
         for (var y = 0; y < h; y += stride) {
            for (var x = 0; x < w; x += stride) {
               var r = img.sample(x, y, 0);
               var g = img.sample(x, y, 1);
               var b = img.sample(x, y, 2);
               if (Math.min(r, g, b) < BPc) clipped++;
               sampled++;
            }
         }
      }
   }

   // Scale up if estimated
   var clippedEst = (stride === 1)
      ? clipped
      : Math.round(clipped * (total / sampled));

   return { clippedEst: clippedEst, total: total, sampled: sampled, stride: stride, bpInfo: bpInfo };
}

function TAPSS_fmtInt(n) {
   // PixInsight JS is old-school; keep it simple
   return "" + Math.round(n);
}


// ============================================================================
// Stretch implementations
//   - Mono
//   - Color linked
//   - Color unlinked
//   - Optional HDR compress (HDRMultiscaleTransform, SASpro style)
//   - Optional Luma-only mode: stretch luma, rescale RGB to preserve chroma
// ============================================================================

function TAPSS_processMonoImage(targetView, targetMedian, iteration) {
   var P = new ProcessContainer;

   // Step 1: robust blackpoint / rescale
   var P001 = new PixelMath;
   P001.expression =
      "Med = med($T);\n" +
      "Sig = 1.4826*MAD($T);\n" +
      "BPraw = Med - " + TAPSS_Parameters.blackpointSigma + "*Sig;\n" +
      "BP = iif(" + (TAPSS_Parameters.noBlackClip ? "1" : "0") + ", min($T), iif(BPraw < min($T), min($T), BPraw));\n" +
      "Rescaled = ($T - BP) / (1 - BP);\n" +
      "Rescaled;";
   P001.useSingleExpression = true;
   P001.symbols = "Med, Sig, BPraw, BP, Rescaled";
   TAPSS_configurePixelMath(P001, false);
   P.add(P001);

   // Step 2: midtones-transfer closed form
   var P002 = new PixelMath;
   P002.expression =
      "((Med($T)-1)*" + targetMedian + "*$T)/(Med($T)*(" + targetMedian + "+$T-1)-" + targetMedian + "*$T)";
   P002.useSingleExpression = true;
   P002.symbols = "L, S";
   TAPSS_configurePixelMath(P002, false);
   P.add(P002);

   // Step 3: optional normalize
   var P003 = new PixelMath;
   P003.expression = TAPSS_Parameters.normalizeImageRange ? "$T/max($T)" : "$T;";
   P003.useSingleExpression = true;
   P003.symbols = "L, Mcolor, S";
   TAPSS_configurePixelMath(P003, true);
   P.add(P003);

   // Step 4: optional HDR compress (SASpro Hermite soft-knee)
   if (TAPSS_Parameters.hdrCompress && TAPSS_Parameters.hdrAmount > 0) {
      TAPSS_addHdrCompressProcess(P, /*isColor=*/false);
   }

   P.executeOn(targetView);
   console.noteln("Mono Image Statistical Stretch completed successfully for iteration " + iteration + ".");
}

function TAPSS_processColorImage(targetView, targetMedian, iteration) {
   // Luma-only mode supports blending:
   // 0 = normal linked, 1 = pure luma-only
   if (TAPSS_Parameters.lumaOnly) {
      var b = Math.max(0, Math.min(1, TAPSS_Parameters.lumaBlend));
      if (b <= 0.000001) {
         // behave like normal linked stretch
         TAPSS_Parameters.lumaOnly = false;              // temporary bypass
         TAPSS_processColorImage(targetView, targetMedian, iteration);
         TAPSS_Parameters.lumaOnly = true;
      } else if (b >= 0.999999) {
         TAPSS_processColorImage_LumaOnly(targetView, targetMedian, iteration);
      } else {
         TAPSS_processColorImage_LumaBlend(targetView, targetMedian, iteration);
      }
      return;
   }
   var P = new ProcessContainer;

   // Step 1: robust blackpoint / rescale based on *luma-like* global stats
   // NOTE: PixelMath cannot do med(Y) where Y is a computed scalar.
   // Workaround: compute luma-median as weighted sum of channel medians.
   // Same for MAD (robust sigma).
   var P001 = new PixelMath;
   P001.expression =
      "cr=0.2126; cg=0.7152; cb=0.0722;\n" +
      "Med = cr*med($T[0]) + cg*med($T[1]) + cb*med($T[2]);\n" +
      "Sig = 1.4826*(cr*MAD($T[0]) + cg*MAD($T[1]) + cb*MAD($T[2]));\n" +
      "MinC = min(min($T[0]),min($T[1]),min($T[2]));\n" +
      "BPraw = Med - " + TAPSS_Parameters.blackpointSigma + "*Sig;\n" +
      "BP = iif(" + (TAPSS_Parameters.noBlackClip ? "1" : "0") + ", MinC, iif(BPraw < MinC, MinC, BPraw));\n" +
      "Rescaled = ($T - BP) / (1 - BP);\n" +
      "Rescaled;";
   P001.useSingleExpression = true;
   P001.symbols = "cr,cg,cb,Med,Sig,MinC,BPraw,BP,Rescaled";
   TAPSS_configurePixelMath(P001, false);
   P.add(P001);

   // Step 2: closed-form midtones mapping using average channel median
   var P002 = new PixelMath;
   P002.expression =
      "MedianColor = avg(Med($T[0]),Med($T[1]),Med($T[2]));\n" +
      "((MedianColor-1)*" + targetMedian + "*$T)/(MedianColor*(" + targetMedian + "+$T-1)-" + targetMedian + "*$T)";
   P002.useSingleExpression = true;
   P002.symbols = "L, MedianColor, S";
   TAPSS_configurePixelMath(P002, false);
   P.add(P002);

   // Step 3: optional normalize
   var P003 = new PixelMath;
   P003.expression = TAPSS_Parameters.normalizeImageRange
      ? "Mcolor=max(max($T[0]),max($T[1]),max($T[2]));\n$T/Mcolor;"
      : "$T;";
   P003.useSingleExpression = true;
   P003.symbols = "L, Mcolor, S";
   TAPSS_configurePixelMath(P003, true);
   P.add(P003);

   // Step 4: optional HDR compress (SASpro Hermite soft-knee)
   if (TAPSS_Parameters.hdrCompress && TAPSS_Parameters.hdrAmount > 0) {
      TAPSS_addHdrCompressProcess(P, /*isColor=*/true);
   }

   P.executeOn(targetView);
   console.noteln("Color Image Statistical Stretch completed successfully for iteration " + iteration + ".");
}

function TAPSS_processColorImage_LumaBlend(targetView, targetMedian, iteration) {
   var P = new ProcessContainer;

   // Use chosen luma mode weights (rec709/601/2020)
   var C = TAPSS_lumaCoeffs();
   var cr = C[0], cg = C[1], cb = C[2];

   // Step 1: robust blackpoint / rescale using chosen luma weights
   var P001 = new PixelMath;
   P001.expression =
      "cr=" + cr + "; cg=" + cg + "; cb=" + cb + ";\n" +
      "Med = cr*med($T[0]) + cg*med($T[1]) + cb*med($T[2]);\n" +
      "Sig = 1.4826*(cr*MAD($T[0]) + cg*MAD($T[1]) + cb*MAD($T[2]));\n" +
      "MinC = min(min($T[0]),min($T[1]),min($T[2]));\n" +
      "BPraw = Med - " + TAPSS_Parameters.blackpointSigma + "*Sig;\n" +
      "BP = iif(" + (TAPSS_Parameters.noBlackClip ? "1" : "0") + ", MinC, iif(BPraw < MinC, MinC, BPraw));\n" +
      "Rescaled = ($T - BP) / (1 - BP);\n" +
      "Rescaled;";
   P001.useSingleExpression = true;
   P001.symbols = "cr,cg,cb,Med,Sig,MinC,BPraw,BP,Rescaled";
   TAPSS_configurePixelMath(P001, false);
   P.add(P001);

   // Step 2: compute Linked stretch + Luma-only stretch, then blend by b
   var b = Math.max(0, Math.min(1, TAPSS_Parameters.lumaBlend));

   var P002 = new PixelMath;
   P002.expression =
      "cr=" + cr + "; cg=" + cg + "; cb=" + cb + ";\n" +

      // Per-pixel luminance
      "Y = cr*$T[0] + cg*$T[1] + cb*$T[2];\n" +

      // Channel medians
      "mr = med($T[0]); mg = med($T[1]); mb = med($T[2]);\n" +

      // Normal linked statistical stretch (your existing linked step2)
      "MedianColor = avg(mr,mg,mb);\n" +
      "Linked = ((MedianColor-1)*" + targetMedian + "*$T)/(MedianColor*(" + targetMedian + "+$T-1)-" + targetMedian + "*$T);\n" +

      // Luma-only stretch: stretch Y -> Y' then scale RGB by Y'/Y
      "mY = cr*mr + cg*mg + cb*mb;\n" +
      "Yp = ((mY-1)*" + targetMedian + "*Y)/(mY*(" + targetMedian + "+Y-1)-" + targetMedian + "*Y);\n" +
      "f = iif(Y<=1.0e-10, 1, Yp/Y);\n" +
      "Luma = $T*f;\n" +

      // Blend: 0 = normal linked, 1 = pure luma-only
      "b=" + b + ";\n" +
      "((1-b)*Linked + b*Luma);";

   P002.useSingleExpression = true;
   P002.symbols = "cr,cg,cb,Y,mr,mg,mb,MedianColor,Linked,mY,Yp,f,Luma,b";
   TAPSS_configurePixelMath(P002, false);
   P.add(P002);

   // Step 3: optional normalize
   var P003 = new PixelMath;
   P003.expression = TAPSS_Parameters.normalizeImageRange
      ? "Mcolor=max(max($T[0]),max($T[1]),max($T[2]));\n$T/Mcolor;"
      : "$T;";
   P003.useSingleExpression = true;
   P003.symbols = "Mcolor";
   TAPSS_configurePixelMath(P003, true);
   P.add(P003);

   // Step 4: optional HDR compress
   if (TAPSS_Parameters.hdrCompress && TAPSS_Parameters.hdrAmount > 0) {
      TAPSS_addHdrCompressProcess(P, /*isColor=*/true);
   }

   P.executeOn(targetView);
   console.noteln("Color (Luma Blend) Statistical Stretch completed successfully for iteration " + iteration + ".");
}


function TAPSS_processColorImage_LumaOnly(targetView, targetMedian, iteration) {
   var P = new ProcessContainer;

   var C = TAPSS_lumaCoeffs();
   var cr = C[0], cg = C[1], cb = C[2];

   // Step 1: robust blackpoint / rescale using chosen luma
   var P001 = new PixelMath;
   P001.expression =
      "cr=" + cr + "; cg=" + cg + "; cb=" + cb + ";\n" +
      "Med = cr*med($T[0]) + cg*med($T[1]) + cb*med($T[2]);\n" +
      "Sig = 1.4826*(cr*MAD($T[0]) + cg*MAD($T[1]) + cb*MAD($T[2]));\n" +
      "MinC = min(min($T[0]),min($T[1]),min($T[2]));\n" +
      "BPraw = Med - " + TAPSS_Parameters.blackpointSigma + "*Sig;\n" +
      "BP = iif(" + (TAPSS_Parameters.noBlackClip ? "1" : "0") + ", MinC, iif(BPraw < MinC, MinC, BPraw));\n" +
      "Rescaled = ($T - BP) / (1 - BP);\n" +
      "Rescaled;";
   P001.useSingleExpression = true;
   P001.symbols = "cr,cg,cb,Med,Sig,MinC,BPraw,BP,Rescaled";
   TAPSS_configurePixelMath(P001, false);
   P.add(P001);

   // Step 2: compute luma, compute luma-stretch, scale RGB by Y'/Y
   var P002 = new PixelMath;
   P002.expression =
      "cr=" + cr + "; cg=" + cg + "; cb=" + cb + ";\n" +
      // Build per-pixel luminance for scaling:
      "Y = cr*$T[0] + cg*$T[1] + cb*$T[2];\n" +
      // Global luma median approximation (PixelMath-safe):
      "m = cr*med($T[0]) + cg*med($T[1]) + cb*med($T[2]);\n" +
      "Yp = ((m-1)*" + targetMedian + "*Y)/(m*(" + targetMedian + "+Y-1)-" + targetMedian + "*Y);\n" +
      "f = iif(Y<=1.0e-10, 1, Yp/Y);\n" +
      "$T*f;";
   P002.useSingleExpression = true;
   P002.symbols = "cr,cg,cb,Y,m,Yp,f";
   TAPSS_configurePixelMath(P002, false);
   P.add(P002);
   // Step 3: optional normalize
   var P003 = new PixelMath;
   P003.expression = TAPSS_Parameters.normalizeImageRange
      ? "Mcolor=max(max($T[0]),max($T[1]),max($T[2]));\n$T/Mcolor;"
      : "$T;";
   P003.useSingleExpression = true;
   P003.symbols = "Mcolor";
   TAPSS_configurePixelMath(P003, true);
   P.add(P003);

   // Step 4: optional HDR compress (SASpro Hermite soft-knee)
   if (TAPSS_Parameters.hdrCompress && TAPSS_Parameters.hdrAmount > 0) {
      TAPSS_addHdrCompressProcess(P, /*isColor=*/true);
   }

   P.executeOn(targetView);
   console.noteln("Color (Luma Only) Statistical Stretch completed successfully for iteration " + iteration + ".");
}

function TAPSS_processUnlinkedColorImage(targetView, targetMedian, iteration) {
   // If luma-only is enabled, unlinked makes no sense; force linked behavior.
   if (TAPSS_Parameters.lumaOnly) {
      // If blend is essentially 0, behave like normal linked stretch (fall through).
      if (TAPSS_Parameters.lumaBlend > 0.000001) {
         TAPSS_processColorImage_LumaOnly(targetView, targetMedian, iteration);
         return;
      }
      // else: fall through to normal linked/unlinked behavior below
   }
   var P = new ProcessContainer;

   // Step 1: robust blackpoint / rescale per channel
   var P001 = new PixelMath;
   P001.useSingleExpression = false;

   // IMPORTANT: In per-channel mode ($T is already the current channel).
   // Do NOT use $T[0]/$T[1]/$T[2] here.
   P001.expression =
      "Med = med($T);\n" +
      "Sig = 1.4826*MAD($T);\n" +
      "BPraw = Med - " + TAPSS_Parameters.blackpointSigma + "*Sig;\n" +
      "BP = iif(" + (TAPSS_Parameters.noBlackClip ? "1" : "0") + ", min($T), iif(BPraw < min($T), min($T), BPraw));\n" +
      "Rescaled = ($T - BP) / (1 - BP);\n" +
      "Rescaled;";

   P001.expression1 =
      "Med = med($T);\n" +
      "Sig = 1.4826*MAD($T);\n" +
      "BPraw = Med - " + TAPSS_Parameters.blackpointSigma + "*Sig;\n" +
      "BP = iif(" + (TAPSS_Parameters.noBlackClip ? "1" : "0") + ", min($T), iif(BPraw < min($T), min($T), BPraw));\n" +
      "Rescaled = ($T - BP) / (1 - BP);\n" +
      "Rescaled;";

   P001.expression2 =
      "Med = med($T);\n" +
      "Sig = 1.4826*MAD($T);\n" +
      "BPraw = Med - " + TAPSS_Parameters.blackpointSigma + "*Sig;\n" +
      "BP = iif(" + (TAPSS_Parameters.noBlackClip ? "1" : "0") + ", min($T), iif(BPraw < min($T), min($T), BPraw));\n" +
      "Rescaled = ($T - BP) / (1 - BP);\n" +
      "Rescaled;";

   P001.symbols = "Med,Sig,BPraw,BP,Rescaled";
   TAPSS_configurePixelMath(P001, false);
   P.add(P001);

   // Step 2: midtones mapping per channel
   var b = Math.max(0, Math.min(1, TAPSS_Parameters.lumaBlend));
   var C = TAPSS_lumaCoeffs();
   var cr = C[0], cg = C[1], cb = C[2];

   var P002 = new PixelMath;
   P002.expression =
      "cr=" + cr + "; cg=" + cg + "; cb=" + cb + ";\n" +

      // per-pixel luminance
      "Y = cr*$T[0] + cg*$T[1] + cb*$T[2];\n" +

      // global medians for linked stretch path
      "mr = med($T[0]); mg = med($T[1]); mb = med($T[2]);\n" +
      "MedianColor = avg(mr,mg,mb);\n" +

      // linked stretch result (same closed-form as your linked color step2)
      "Linked = ((MedianColor-1)*" + targetMedian + "*$T)/(MedianColor*(" + targetMedian + "+$T-1)-" + targetMedian + "*$T);\n" +

      // luma-only stretch result: compute Y' then scale RGB by Y'/Y
      "mY = cr*mr + cg*mg + cb*mb;\n" +
      "Yp = ((mY-1)*" + targetMedian + "*Y)/(mY*(" + targetMedian + "+Y-1)-" + targetMedian + "*Y);\n" +
      "f = iif(Y<=1.0e-10, 1, Yp/Y);\n" +
      "Luma = $T*f;\n" +

      // blend: 0=linked, 1=luma-only
      "b=" + b + ";\n" +
      "((1-b)*Linked + b*Luma);";

   P002.useSingleExpression = true;
   P002.symbols = "cr,cg,cb,Y,mr,mg,mb,MedianColor,Linked,mY,Yp,f,Luma,b";
   TAPSS_configurePixelMath(P002, false);
   P.add(P002);

   // Step 3: optional normalize per channel
   var P003 = new PixelMath;
   P003.useSingleExpression = false;

   P003.expression  = TAPSS_Parameters.normalizeImageRange ? "$T/max($T)" : "$T;";
   P003.expression1 = TAPSS_Parameters.normalizeImageRange ? "$T/max($T)" : "$T;";
   P003.expression2 = TAPSS_Parameters.normalizeImageRange ? "$T/max($T)" : "$T;";

   TAPSS_configurePixelMath(P003, true);
   P.add(P003);

   // Step 4: optional HDR compress (SASpro: compress luma then rescale RGB)
   if (TAPSS_Parameters.hdrCompress && TAPSS_Parameters.hdrAmount > 0) {
      TAPSS_addHdrCompressProcess(P, /*isColor=*/true);
   }

   P.executeOn(targetView);
   console.noteln("Unlinked Color Image Stretch completed successfully for iteration " + (iteration || 1) + ".");
}


// ============================================================================
// Global parameters object (persisted)
// ============================================================================


function executeStatisticalStretch( view, s )
{
   logStep( "[8] Image Stretch" );

   if ( view == null || view.isNull )
      throw new Error( "Statistical Stretch requires a valid _work image." );

   TAPSS_Parameters.targetMedian =
      clampValue( s.statTargetMedian, 0.0, 1.0 );
   TAPSS_Parameters.blackpointSigma =
      clampValue( s.statBlackpointSigma, 0.0, 10.0 );
   TAPSS_Parameters.noBlackClip = !!s.statNoBlackClip;
   TAPSS_Parameters.hdrCompress = !!s.statHDRCompress;
   TAPSS_Parameters.hdrAmount =
      clampValue( s.statHDRAmount, 0.0, 1.0 );
   TAPSS_Parameters.hdrKnee =
      clampValue( s.statHDRKnee, 0.10, 1.00 );
   TAPSS_Parameters.lumaOnly = !!s.statLumaOnly;
   TAPSS_Parameters.lumaMode = s.statLumaMode || "rec709";
   TAPSS_Parameters.lumaBlend =
      clampValue( s.statLumaBlend, 0.0, 1.0 );
   TAPSS_Parameters.normalizeImageRange = !!s.statNormalize;
   TAPSS_Parameters.linkedStretch =
      TAPSS_Parameters.lumaOnly ? true : !!s.statLinkedStretch;
   TAPSS_Parameters.curvesBoost =
      clampValue( s.statCurvesBoost, 0.0, 0.50 );

   console.writeln( "Target image                 : " + view.id );
   console.writeln( "Target Median                : " + TAPSS_Parameters.targetMedian.toFixed( 2 ) );
   console.writeln( "Blackpoint Sigma             : " + TAPSS_Parameters.blackpointSigma.toFixed( 2 ) );
   console.writeln( "No Black Clip                : " + ( TAPSS_Parameters.noBlackClip ? "ON" : "OFF" ) );
   console.writeln( "HDR Compress                 : " + ( TAPSS_Parameters.hdrCompress ? "ON" : "OFF" ) );
   console.writeln( "HDR Amount / Knee            : " +
      TAPSS_Parameters.hdrAmount.toFixed( 2 ) + " / " +
      TAPSS_Parameters.hdrKnee.toFixed( 2 ) );
   console.writeln( "Luma Only                    : " + ( TAPSS_Parameters.lumaOnly ? "ON" : "OFF" ) );
   console.writeln( "Luma Mode / Blend            : " +
      TAPSS_Parameters.lumaMode + " / " +
      TAPSS_Parameters.lumaBlend.toFixed( 2 ) );
   console.writeln( "Normalize [0,1]              : " + ( TAPSS_Parameters.normalizeImageRange ? "ON" : "OFF" ) );
   console.writeln( "Linked Stretch               : " + ( TAPSS_Parameters.linkedStretch ? "ON" : "OFF" ) );
   console.writeln( "Curves Boost                 : " + TAPSS_Parameters.curvesBoost.toFixed( 2 ) );

   // Diagnostic equivalent of the original "Calculate Clipped Pixels" control.
   try
   {
      var clipImage = new Image( view.image );
      var clip = TAPSS_estimateClippedPixels_Blackpoint( clipImage, 1000000 );
      var clipPct = clip.total > 0 ? 100.0 * clip.clippedEst / clip.total : 0.0;
      console.writeln(
         "Estimated clipped pixels      : " +
         TAPSS_fmtInt( clip.clippedEst ) + " / " +
         TAPSS_fmtInt( clip.total ) + " (" +
         clipPct.toFixed( 4 ) + "%)"
      );
      clipImage.free();
   }
   catch ( clipError )
   {
      console.warningln( "Clipped-pixel estimate unavailable: " + clipError.message );
   }

   // The standalone v2.3 UI defaults to one iteration / no auto convergence.
   if ( view.image.isColor )
   {
      if ( TAPSS_Parameters.linkedStretch )
         TAPSS_processColorImage( view, TAPSS_Parameters.targetMedian, 1 );
      else
         TAPSS_processUnlinkedColorImage( view, TAPSS_Parameters.targetMedian, 1 );
   }
   else
   {
      TAPSS_processMonoImage( view, TAPSS_Parameters.targetMedian, 1 );
   }

   if ( TAPSS_Parameters.curvesBoost > 0 )
      TAPSS_applyFinalCurve( view, TAPSS_Parameters.targetMedian );

   TAPSS_disableSTF( view );
   CoreApplication.processEvents();

   console.noteln( "Statistical Stretch completed." );
}

function executeLukeHTStretch( view, s )
{
   logStep( "[8] Image Stretch - Luke's HT Stretch" );

   if ( view == null || view.isNull )
      throw new Error( "Luke's HT Stretch requires a valid _work image." );

   // User-defined automatic policy:
   // SPCC enabled -> LINKED; SPCC disabled -> UNLINKED.
   // A linked RGB expression requires a color target, so mono data safely falls
   // back to the unlinked expression even if SPCC was enabled.
   var linked = !!s.spcc && view.image.isColor;

   var P = new PixelMath;
   if ( linked )
   {
      P.symbols = "C=-2.8, B=0.20, m, d, c";
      P.expression =
         "m=(med($T[0])+med($T[1])+med($T[2]))/3;\n" +
         "d=(mdev($T[0])+mdev($T[1])+mdev($T[2]))/3;\n" +
         "c=min(max(0,m+C*1.4826*d),1);\n" +
         "mtf(mtf(B,m-c),max(0,($T-c)/~c))";
   }
   else
   {
      P.symbols = "C=-2.8, B=0.20, c";
      P.expression =
         "c=min(max(0,med($T)+C*1.4826*mdev($T)),1);\n" +
         "mtf(mtf(B,med($T)-c),max(0,($T-c)/~c))";
   }

   TAPIC_configurePixelMathInPlace( P );

   console.writeln( "Stretch method               : Luke's HT Stretch" );
   console.writeln( "C / B                        : -2.80 / 0.20" );
   console.writeln( "Automatic mode               : " + ( linked ? "LINKED (SPCC enabled)" : "UNLINKED" ) );
   if ( !!s.spcc && !view.image.isColor )
      console.warningln( "Luke's HT Stretch: SPCC is enabled, but the target is monochrome. Using UNLINKED mode because the LINKED formula requires RGB channels." );

   if ( !P.executeOn( view ) )
      throw new Error( "Luke's HT Stretch PixelMath execution failed or was aborted." );

   TAPSS_disableSTF( view );
   CoreApplication.processEvents();
   console.noteln( "Luke's HT Stretch completed." );
}

function executeImageStretch( view, s )
{
   if ( s.imageStretchEngine == IMAGE_STRETCH_ENGINE_LUKE )
      executeLukeHTStretch( view, s );
   else
      executeStatisticalStretch( view, s );
}


// =====================================================================
// 10. DARK STRUCTURE ENHANCE v1.1
// =====================================================================

/*
 * Adapted from DarkStructureEnhance v1.1.
 * Original algorithm: Carlos Sonnenstein (PTeam)
 * PixInsight JavaScript implementation: Oriol Lehmkuhl (PTeam)
 * Copyright (C) 2009 Carlos Sonnenstein & Oriol Lehmkuhl
 * License: GNU GPL v3 or later.
 *
 * The processing engine is integrated below with TAPDSE_ names.
 * v2.7.8 follows the supplied 1.9.4-compatible script's ATrousWaveletTransformV1
 * implementation and resolves its process enums from live process instances.
 */

function TAPDSE_ScalingFunction( kernel, name, size )
{
   this.kernel = kernel;
   this.name = name;
   this.size = size;
}

var TAPDSE_scalingFunctions = [];

TAPDSE_scalingFunctions[0] = new TAPDSE_ScalingFunction(
   [ 0.29289322, 0.5, 0.29289322,
     0.5,        1.0, 0.5,
     0.29289322, 0.5, 0.29289322 ],
   "3x3 Linear Interpolation", 3 );

TAPDSE_scalingFunctions[1] = new TAPDSE_ScalingFunction(
   [ 1/256, 1/64, 3/128, 1/64, 1/256,
     1/64,  1/16, 3/32,  1/16, 1/64,
     3/128, 3/32, 9/64,  3/32, 3/128,
     1/64,  1/16, 3/32,  1/16, 1/64,
     1/256, 1/64, 3/128, 1/64, 1/256 ],
   "5x5 B3 Spline", 5 );

function TAPDSE_doAuxiliarImage( data )
{
   var view = data.targetView;
   var sourceWindow = view.window;

   var mask = new ImageWindow(
      view.image.width,
      view.image.height,
      view.image.numberOfChannels,
      sourceWindow.bitsPerSample,
      sourceWindow.isFloatSample,
      view.image.colorSpace != ColorSpace_Gray,
      uniqueImageId( "DSE_AuxMask" )
   );

   var maskView = mask.mainView;
   maskView.beginProcess( UndoFlag_NoSwapFile );
   maskView.image.apply( view.image );
   maskView.endProcess();

   var nStarMask = 6;
   var auxLayers = new Array( nStarMask );
   for ( var i = 0; i < nStarMask; ++i )
      auxLayers[i] = [ true, true, 1.00, 3.00, 0.000, false, 0, 0.50, 2, 5, false, true, 1.0, 0.02000 ];
   auxLayers[nStarMask] = [ false, true, 1.00, 3.00, 0.000, false, 0, 0.50, 2, 5, false, false, 0.50, 0.02000 ];

   var wavlets = new ATrousWaveletTransformV1;
   wavlets.version = 257;
   wavlets.layers = auxLayers;
   wavlets.scaleDelta = 0;
   wavlets.scalingFunctionData = TAPDSE_scalingFunctions[data.scalingFunction].kernel;
   wavlets.scalingFunctionKernelSize = TAPDSE_scalingFunctions[data.scalingFunction].size;
   wavlets.scalingFunctionName = TAPDSE_scalingFunctions[data.scalingFunction].name;
   wavlets.largeScaleFunction =
      TAP_resolveEnumValue( wavlets, ATrousWaveletTransformV1, [ "NoFunction" ], 0 );
   wavlets.curveBreakPoint = 0.75;
   wavlets.noiseThresholdingAmount = 0.00;
   wavlets.noiseThreshold = 3.00;
   wavlets.lowRange = 0.000;
   wavlets.highRange = 0.000;
   wavlets.previewMode =
      TAP_resolveEnumValue( wavlets, ATrousWaveletTransformV1, [ "Disabled" ], 0 );
   wavlets.previewLayer = 0;
   wavlets.toLuminance = true;
   wavlets.toChrominance = true;
   wavlets.linear = false;
   wavlets.executeOn( maskView, false );

   return mask;
}

function TAPDSE_doMask( data )
{
   var view = data.targetView;
   var sourceWindow = view.window;

   var mask = new ImageWindow(
      view.image.width,
      view.image.height,
      view.image.numberOfChannels,
      sourceWindow.bitsPerSample,
      sourceWindow.isFloatSample,
      view.image.colorSpace != ColorSpace_Gray,
      uniqueImageId( "DSE_Mask" )
   );

   var maskView = mask.mainView;
   maskView.beginProcess( UndoFlag_NoSwapFile );
   maskView.image.apply( view.image );
   maskView.endProcess();

   var rgb = new RGBWorkingSpace;
   rgb.channels =
   [
      [ 0.333333, 0.648431, 0.330856 ],
      [ 0.333333, 0.321152, 0.597871 ],
      [ 0.333333, 0.155886, 0.066044 ]
   ];
   rgb.gamma = 2.20;
   rgb.sRGBGamma = true;
   rgb.applyGlobalRGBWS = false;
   rgb.executeOn( maskView, false );

   var auxMask = TAPDSE_doAuxiliarImage( data );

   var pm = new PixelMath;
   pm.expression = "$T -" + auxMask.mainView.id;
   pm.useSingleExpression = true;
   pm.use64BitWorkingImage = false;
   pm.rescale = false;
   pm.rescaleLower = 0;
   pm.rescaleUpper = 1;
   pm.truncate = true;
   pm.truncateLower = 0;
   pm.truncateUpper = 1;
   pm.createNewImage = false;
   pm.executeOn( maskView, false );

   auxMask.forceClose();

   var auxLayers = new Array( data.numberOfLayers );
   for ( var i = 0; i < data.numberOfLayers; ++i )
      auxLayers[i] = [ false, true, 1.00, 3.00, 0.000, false, 0, 0.50, 2, 5, false, false, 0.50, 0.02000 ];
   auxLayers[data.numberOfLayers] = [ true, true, 1.00, 3.00, 0.000, false, 0, 0.50, 2, 5, false, false, 0.50, 0.02000 ];

   var wavlets = new ATrousWaveletTransformV1;
   wavlets.version = 257;
   wavlets.layers = auxLayers;
   wavlets.scaleDelta = 0;
   wavlets.scalingFunctionData = TAPDSE_scalingFunctions[data.scalingFunction].kernel;
   wavlets.scalingFunctionKernelSize = TAPDSE_scalingFunctions[data.scalingFunction].size;
   wavlets.scalingFunctionName = TAPDSE_scalingFunctions[data.scalingFunction].name;
   wavlets.largeScaleFunction =
      TAP_resolveEnumValue( wavlets, ATrousWaveletTransformV1, [ "NoFunction" ], 0 );
   wavlets.curveBreakPoint = 0.75;
   wavlets.noiseThresholdingAmount = 0.00;
   wavlets.noiseThreshold = 3.00;
   wavlets.lowRange = 0.000;
   wavlets.highRange = 0.000;
   wavlets.previewMode =
      TAP_resolveEnumValue( wavlets, ATrousWaveletTransformV1, [ "Disabled" ], 0 );
   wavlets.previewLayer = 0;
   wavlets.toLuminance = true;
   wavlets.toChrominance = true;
   wavlets.linear = false;
   wavlets.executeOn( maskView, false );

   pm = new PixelMath;
   pm.expression = maskView.id + "-" + view.id;
   pm.expression1 = "";
   pm.expression2 = "";
   pm.useSingleExpression = true;
   pm.symbols = "";
   pm.use64BitWorkingImage = false;
   pm.rescale = false;
   pm.rescaleLower = 0;
   pm.rescaleUpper = 1;
   pm.truncate = true;
   pm.truncateLower = 0;
   pm.truncateUpper = 1;
   pm.createNewImage = false;
   pm.executeOn( maskView, false );

   if ( view.image.colorSpace != ColorSpace_Gray )
   {
      var toGray = new ConvertToGrayscale;
      toGray.executeOn( maskView, false );
   }

   var rescale = new Rescale;
   rescale.mode = TAP_resolveEnumValue( rescale, Rescale, [ "RGBK" ], 0 );
   rescale.executeOn( maskView, false );

   var nr = new ATrousWaveletTransformV1;
   nr.version = 257;
   var recursiveFilter =
      TAP_resolveEnumValue( nr, ATrousWaveletTransformV1, [ "Recursive" ], 0 );

   nr.layers =
   [
      [ false, true, 1.00, 3.00, 0.000, false, recursiveFilter, 1.00, 5, 5, false, false, 0.50, 0.02000 ],
      [ true,  true, 1.00, 3.00, 0.000, true,  recursiveFilter, 1.00, 5, 5, false, false, 0.50, 0.02000 ],
      [ true,  true, 1.00, 3.00, 0.000, false, recursiveFilter, 0.50, 2, 5, false, false, 0.50, 0.02000 ]
   ];
   nr.scaleDelta = 0;
   nr.scalingFunctionData =
   [
      0.292893, 0.5, 0.292893,
      0.5, 1, 0.5,
      0.292893, 0.5, 0.292893
   ];
   nr.scalingFunctionKernelSize = 3;
   nr.scalingFunctionName = "3x3 Linear Interpolation";
   nr.largeScaleFunction =
      TAP_resolveEnumValue( nr, ATrousWaveletTransformV1, [ "NoFunction" ], 0 );
   nr.toLuminance = true;
   nr.toChrominance = false;
   nr.linear = false;
   nr.executeOn( maskView, false );

   return mask;
}

function executeDarkStructureEnhance( view, s )
{
   logStep( "[11] Dark Structure Enhance" );

   var amount = clampValue( s.dseAmount, 0.0, 0.99 );
   var data =
   {
      targetView: view,
      numberOfLayers: Math.round( clampValue( s.dseLayers, 7, 12 ) ),
      scalingFunction: Math.round( clampValue( s.dseScalingFunction, 0, TAPDSE_scalingFunctions.length - 1 ) ),
      median: 0.5 * amount + 0.5,
      iterations: Math.round( clampValue( s.dseIterations, 1, 10 ) ),
      viewMask: !!s.dseExtractMask
   };

   console.writeln( "Target image      : " + view.id );
   console.writeln( "Layers to remove  : " + data.numberOfLayers );
   console.writeln( "Extract mask      : " + ( data.viewMask ? "ON" : "OFF" ) );
   console.writeln( "Scaling function  : " + TAPDSE_scalingFunctions[data.scalingFunction].name );
   console.writeln( "Amount            : " + amount.toFixed( 2 ) );
   console.writeln( "Iterations        : " + data.iterations );

   var hist = new HistogramTransformation;
   hist.H =
   [
      [ 0, 0.5,         1, 0, 1 ],
      [ 0, 0.5,         1, 0, 1 ],
      [ 0, 0.5,         1, 0, 1 ],
      [ 0, data.median, 1, 0, 1 ],
      [ 0, 0.5,         1, 0, 1 ]
   ];

   var mask = TAPDSE_doMask( data );
   var pc = new ProcessContainer;

   for ( var i = 0; i < data.iterations; ++i )
   {
      pc.add( hist );
      pc.setMask( i, mask, false );
   }

   data.targetView.beginProcess();
   pc.executeOn( data.targetView, false );
   data.targetView.endProcess();

   mask.removeMaskReferences();

   if ( data.viewMask )
   {
      mask.show();
   }
   else
   {
      mask.forceClose();
   }

   CoreApplication.processEvents();
   console.noteln( "Dark Structure Enhance completed." );
}


// =====================================================================
// 11. COSMICPHOTONS SCREEN STARS
// =====================================================================

/*
 * Processing branch adapted from ScreenStars v1.4 by Mike Cranfield.
 * Copyright (C) 2023,2024 Mike Cranfield.
 * License: GNU GPL v3 or later.
 *
 * Fixed workflow configuration:
 *   Mode: Star replacement
 *   Method: Screen/Unscreen
 *   Enable reverse stretch: OFF
 *   Starless view: current _work image
 *   Stars view: NBtoRGB_stars
 *   Create new image: ON
 *   Output id: Final_Image
 */

function TAPSCREEN_findNBtoRGBStarsView()
{
   var exact = TAPSTAR_getWindowById( "NBtoRGB_stars" );
   if ( exact != null )
      return exact.mainView;

   var windows = ImageWindow.windows;
   for ( var i = windows.length - 1; i >= 0; --i )
   {
      var id = windows[i].mainView.id;
      if ( id.indexOf( "NBtoRGB_stars" ) == 0 )
         return windows[i].mainView;
   }

   return null;
}

function TAPSCREEN_isCompatible( view1, view2 )
{
   if ( view1 == null || view1.isNull || view2 == null || view2.isNull )
      return "view not specified";
   if ( view1.image.width != view2.image.width )
      return "view geometry differs";
   if ( view1.image.height != view2.image.height )
      return "view geometry differs";
   if ( view1.image.isColor != view2.image.isColor )
      return "views mix colour and greyscale";
   if ( view1.id == view2.id )
      return "views are the same view";
   return "";
}

function executeScreenStars( starlessView, starsView )
{
   logStep( "[13] Blend Image + Stars" );

   var compatibility = TAPSCREEN_isCompatible( starlessView, starsView );
   if ( compatibility != "" )
      throw new Error(
         "Blend Image + Stars cannot combine the selected views: " + compatibility + "."
      );

   console.writeln( "Mode                   : Star replacement" );
   console.writeln( "Method                 : Screen / Unscreen" );
   console.writeln( "Enable reverse stretch : OFF" );
   console.writeln( "Starless view          : " + starlessView.id );
   console.writeln( "Stars view             : " + starsView.id );
   console.writeln( "Create new image       : ON" );

   var outputId = uniqueImageId( "Final_Image" );
   console.writeln( "Starry image id        : " + outputId );

   var PM = new PixelMath;
   PM.expression =
      "E1 = " + starlessView.id + ";\n" +
      "E2 = " + starsView.id + ";\n" +
      "(E1 + E2 - E1*E2)";
   PM.useSingleExpression = true;
   PM.symbols = "E1, E2";
   PM.clearImageCacheAndExit = false;
   PM.cacheGeneratedImages = false;
   PM.generateOutput = true;
   PM.singleThreaded = false;
   PM.optimization = true;
   PM.use64BitWorkingImage = false;
   PM.rescale = false;
   PM.rescaleLower = 0;
   PM.rescaleUpper = 1;
   PM.truncate = true;
   PM.truncateLower = 0;
   PM.truncateUpper = 1;
   PM.createNewImage = true;
   PM.showNewImage = true;
   PM.newImageId = outputId;
   PM.newImageWidth = 0;
   PM.newImageHeight = 0;
   PM.newImageAlpha = false;
   PM.newImageColorSpace = PixelMath.SameAsTarget;
   PM.newImageSampleFormat = PixelMath.SameAsTarget;

   if ( !PM.executeOn( starlessView ) )
      throw new Error( "Blend Image + Stars / Star replacement failed." );

   var resultWindow = TAPSTAR_getWindowById( outputId );
   if ( resultWindow == null )
      throw new Error( "Blend Image + Stars completed but the Final_Image window could not be located." );

   resultWindow.show();
   resultWindow.bringToFront();
   resultWindow.zoomToOptimalFit();
   CoreApplication.processEvents();

   console.noteln( "Blend Image + Stars complete: " + outputId );
   return resultWindow.mainView;
}


// =====================================================================
// COLLAPSIBLE / DROP-DOWN SECTION CONTROL
// =====================================================================

function TAP_CollapsibleSection( parent, title, expanded, checked )
{
   this.control = new Control( parent );
   this.headerControl = new Control( this.control );
   this.enabledCheckBox = new CheckBox( this.headerControl );
   this.header = new PushButton( this.headerControl );
   this.body = new Control( this.control );
   this.title = title;
   this.expanded = !!expanded;
   this.onToggle = null;

   var self = this;

   this.enabledCheckBox.checked = checked !== false;
   this.enabledCheckBox.toolTip =
      "<p>Enable or disable this processing stage without opening the drop-down.</p>";

   var stageToolTip = TAP_STAGE_TOOLTIPS[title];
   if ( stageToolTip != null && stageToolTip.length > 0 )
      this.header.toolTip = stageToolTip;

   var headerSizer = new HorizontalSizer;
   headerSizer.margin = 0;
   headerSizer.spacing = 3;
   headerSizer.add( this.enabledCheckBox );
   headerSizer.add( this.header, 100 );
   this.headerControl.sizer = headerSizer;

   this.control.sizer = new VerticalSizer;
   this.control.sizer.margin = 0;
   this.control.sizer.spacing = 1;
   this.control.sizer.add( this.headerControl );
   this.control.sizer.add( this.body );

   this.setBodySizer = function( sizer )
   {
      self.body.sizer = sizer;
   };

   this.setExpanded = function( value, notify )
   {
      self.expanded = !!value;

      // Always release any height locks before changing visibility. Previous
      // builds could retain a stale expanded height after a section was closed,
      // leaving large blank gaps between subsequent stage headers.
      try { self.control.setVariableHeight(); } catch ( e0 ) {}
      try { self.headerControl.setVariableHeight(); } catch ( e1 ) {}
      try { self.body.setVariableHeight(); } catch ( e2 ) {}

      self.body.visible = self.expanded;
      self.header.text = ( self.expanded ? "▼  " : "▶  " ) + self.title;

      if ( notify !== false && self.onToggle )
         self.onToggle( self.expanded );
   };

   this.header.onClick = function()
   {
      self.setExpanded( !self.expanded, true );
   };

   this.setExpanded( this.expanded, false );
}



