        if ( this.chunkSize > 2048 ) this.chunkSize = 2048;
        if ( this.overlap   < 0    ) this.overlap   = 0;
        if ( this.overlap   >= this.chunkSize ) this.overlap = Math.max( 0, this.chunkSize - 1 );
