var STAR_ENGINE_STARNET = 1;

var STAR_STRETCH_ENGINE_NBTORGB = 0;
var STAR_STRETCH_ENGINE_SETIASTRO = 1;

var FB_MODE_FULL    = 0;
var FB_MODE_CUSTOM  = 1;

var IMAGE_STRETCH_ENGINE_SETIASTRO = 0;
var IMAGE_STRETCH_ENGINE_LUKE      = 1;

var TAP_DEFAULT_EXECUTION_ORDER = [
   "optical",
   "adbe",
   "spcc",
   "blurx",
   "noisex",
   "starx",
   "findbg",
   "statstretch",
   "nbn",
   "rangehdr",
   "maskscurves",
   "lighthouse",
   "dse",
   "starstretch",
   "screenstars"
];

var TAP_STAGE_LABELS = {
   optical:     "1. Optical Correction",
   adbe:        "2. Automatic DBE",
   spcc:        "3. SPCC",
   blurx:       "4. Sharpening",
   noisex:      "5. Noise Reduction",
   starx:       "6. Star Removal",
   findbg:      "7. Find and Neutralize Background",
   statstretch: "8. Image Stretch",
   nbn:         "9. Narrowband Normalization",
   rangehdr:    "10. Range Selection and HDR",
   maskscurves: "11. Masks and Curves",
   lighthouse:  "12. Lighthouse",
   dse:         "13. Dark Structure Enhance",
   starstretch: "14. Star Stretch",
   screenstars: "15. Blend Image + Stars"
};

var TAP_STAGE_TOOLTIPS = {
   "1. Optical Correction":
      "<p>Corrects optical blur and aberrations before the main processing stages. Depending on the selected engine, AstroTemps uses BlurXTerminator in correction-only mode or Cosmic Clarity SASpro to improve star shapes and optical defects without applying the main sharpening pass.</p>",

   "2. Automatic DBE":
      "<p>Models and removes large-scale gradients caused by light pollution, moonlight, uneven illumination, or other background variations. This helps establish a cleaner and more uniform background before color calibration and detail processing.</p>",

   "3. SPCC":
      "<p>Performs Spectrophotometric Color Calibration. SPCC uses the image's astrometric solution together with the selected camera/filter spectral responses to establish a physically meaningful color balance. If the image has no astrometric solution, AstroTemps can run ImageSolver first.</p>",

   "4. Sharpening":
      "<p>Enhances stellar and nonstellar detail after optical correction. The selected sharpening engine can improve the definition of nebular structures, galaxies, and stars while using the parameters configured in this section.</p>",

   "5. Noise Reduction":
      "<p>Reduces random luminance and color noise while attempting to preserve real astronomical structure. Depending on the selected engine, AstroTemps can use NoiseXTerminator or Cosmic Clarity SASpro with the configured separation and detail controls.</p>",

   "6. Star Removal":
      "<p>Separates the image into a starless image and, when enabled, a stars-only image. This allows nebulae and background structures to be processed independently from the stars and later recombined near the end of the workflow.</p>",

   "7. Find and Neutralize Background":
      "<p>Finds a representative background region and uses it to neutralize unwanted color casts in the sky background. Full Image mode searches automatically, while Custom mode lets the user choose a suitable background area.</p>",

   "8. Image Stretch":
      "<p>Converts the linear image into a nonlinear image suitable for visual interpretation and later processing. SetiAstro's Statistical Stretch provides adjustable controls, while Luke's HT Stretch offers a fast fixed PixelMath stretch and automatically selects linked or unlinked behavior from the SPCC setting.</p>",

   "9. Narrowband Normalization":
      "<p>Balances narrowband channels after stretching to improve the relative contribution of emission lines such as H-alpha, OIII, and SII. It is primarily intended for narrowband data and provides an interactive preview before the result is accepted.</p>",

   "10. Range Selection and HDR":
      "<p>Creates a luminosity-based RangeSelection mask and then applies HDRMultiscaleTransform through that mask. This helps compress strong brightness differences and reveal structure in bright regions while protecting areas outside the selected luminosity range.</p>",

   "11. Masks and Curves":
      "<p>Creates Red, Yellow, Green, Cyan, Blue, and Magenta color masks, softens them with MaskBlur, and applies CurvesTransformation sequentially through each mask. This provides selective control over different color regions without globally changing the entire image.</p>",

   "12. Lighthouse":
      "<p>Opens the integrated Lighthouse interactive editor on the current working image. It provides an additional hands-on processing stage for tonal and image refinements before the final enhancement and star-processing stages.</p>",

   "13. Dark Structure Enhance":
      "<p>Enhances dark structures such as dust lanes and absorption features. A multiscale mask isolates darker structures so they can be emphasized without applying the same adjustment uniformly across the whole image.</p>",

   "14. Star Stretch":
      "<p>Processes the stars-only image independently from the starless image. The selected method stretches stellar brightness and color so the stars can be controlled separately before they are recombined with the processed background.</p>",

   "15. Blend Image + Stars":
      "<p>Recombines the processed starless image with the processed stars-only image to create the final starry result. The screen/unscreen blend preserves the separation workflow while restoring the stars at the end of processing.</p>"
};

function TAP_normalizeExecutionOrder( order )
{
   var result = [];
   var i;
   if ( order != null )
   {
      for ( i = 0; i < order.length; ++i )
      {
         var id = String( order[i] );
         if ( TAP_STAGE_LABELS[id] != null && result.indexOf( id ) < 0 )
            result.push( id );
      }
   }

   for ( i = 0; i < TAP_DEFAULT_EXECUTION_ORDER.length; ++i )
   {
      var defaultId = TAP_DEFAULT_EXECUTION_ORDER[i];
      if ( result.indexOf( defaultId ) < 0 )
         result.push( defaultId );
   }
   return result;
}

function TAP_executionOrderText( order )
{
   var parts = [];
   for ( var i = 0; i < order.length; ++i )
      parts.push( ( i + 1 ) + ". " + TAP_STAGE_LABELS[order[i]].replace( /^\d+(?:\.\d+)?\.\s*/, "" ) );
   return parts.join( "  →  " );
}

