function TAP_readParamAuto( key, defaultValue )
{
   if ( !Parameters.has( key ) )
      return defaultValue;
   if ( typeof defaultValue == "boolean" ) return Parameters.getBoolean( key );
   if ( typeof defaultValue == "number" )
   {
      // Integer fields remain integers; real controls use getReal.
      if ( Math.floor( defaultValue ) == defaultValue &&
           ( key.indexOf( "Version" ) >= 0 || key.indexOf( "Engine" ) >= 0 ||
             key.indexOf( "Iterations" ) >= 0 || key.indexOf( "Layers" ) >= 0 ||
             key.indexOf( "ScalingFunction" ) >= 0 || key.indexOf( "ChunkSize" ) >= 0 ||
             key.indexOf( "Mode" ) >= 0 ) )
         return Parameters.getInteger( key );
      return Parameters.getReal( key );
   }
   return Parameters.getString( key );
}

function loadSettingsFromParameters()
{
   var s = defaultSettings();
   if ( Parameters.has( "createCopy" ) ) s.createCopy = Parameters.getBoolean( "createCopy" );
   if ( Parameters.has( "backupEachProcess" ) ) s.backupEachProcess = Parameters.getBoolean( "backupEachProcess" );
   if ( Parameters.has( "customizeOrder" ) ) s.customizeOrder = Parameters.getBoolean( "customizeOrder" );
   if ( Parameters.has( "executionOrder" ) )
      s.executionOrder = TAP_normalizeExecutionOrder( Parameters.getString( "executionOrder" ).split( "|" ) );
   if ( Parameters.has( "autoSTF" ) ) s.autoSTF = Parameters.getBoolean( "autoSTF" );

   for ( var k in s )
      if ( k != "createCopy" && k != "backupEachProcess" && k != "customizeOrder" &&
           k != "executionOrder" && k != "autoSTF" )
         s[k] = TAP_readParamAuto( k, s[k] );

   // Compatibility with v2.6 Process Icons / saved parameters.
   if ( Parameters.has( "spccFilter" ) &&
        !Parameters.has( "spccRedFilter" ) )
   {
      var oldFilter = Parameters.getInteger( "spccFilter" );
      if ( oldFilter == 1 )
      {
         s.spccRedFilter   = "Optolong L-Quad Enhance R";
         s.spccGreenFilter = "Optolong L-Quad Enhance G";
         s.spccBlueFilter  = "Optolong L-Quad Enhance B";
      }
   }

   if ( Parameters.has( "starGenerate" ) && !Parameters.has( "starOutputStars" ) )
      s.starOutputStars = Parameters.getBoolean( "starGenerate" );
   if ( Parameters.has( "starLargeOverlap" ) && !Parameters.has( "starOverlap" ) )
      s.starOverlap = Parameters.getBoolean( "starLargeOverlap" ) ? 0.50 : 0.20;

   /*
    * Compatibility migration for v2.8.0-v2.8.2 NBN test builds.
    * Those builds used zero as the UI/default value for several multiplicative
    * NBN controls. The installed CosmicPhotons process reports a neutral/default
    * value of 1.0, and OIII/SII boost reject values below 0.5.
    */
   var legacyInvalidNBN =
      !isFinite( s.nbnO3Boost ) || s.nbnO3Boost < 0.5 || s.nbnO3Boost > 2.0 ||
      !isFinite( s.nbnS2Boost ) || s.nbnS2Boost < 0.5 || s.nbnS2Boost > 2.0 ||
      !isFinite( s.nbnHighlightReduction ) || s.nbnHighlightReduction <= 0 ||
      !isFinite( s.nbnBrightness ) || s.nbnBrightness <= 0;

   if ( legacyInvalidNBN )
   {
      if ( !isFinite( s.nbnHaBlend ) || s.nbnHaBlend == 0 )
         s.nbnHaBlend = 0.600;

      if ( !isFinite( s.nbnO3Boost ) || s.nbnO3Boost < 0.5 || s.nbnO3Boost > 2.0 )
         s.nbnO3Boost = 1.000;

      if ( !isFinite( s.nbnS2Boost ) || s.nbnS2Boost < 0.5 || s.nbnS2Boost > 2.0 )
         s.nbnS2Boost = 1.000;

      if ( !isFinite( s.nbnHighlightReduction ) || s.nbnHighlightReduction <= 0 )
         s.nbnHighlightReduction = 1.000;

      if ( !isFinite( s.nbnBrightness ) || s.nbnBrightness <= 0 )
         s.nbnBrightness = 1.000;

      console.noteln(
         "Migrated legacy NBN test settings to CosmicPhotons neutral defaults."
      );
   }

   // BlurXTerminator currently defines Sharpen Stars on [0.00, 0.70].
   // Older AstroTemps builds exposed 0.71-1.00, a dead/invalid UI range.
   if ( !isFinite( s.sharpenStars ) )
      s.sharpenStars = 0.35;
   s.sharpenStars = clampValue( s.sharpenStars, 0.0, 0.70 );

   return s;
}

function logHeader()
{
   console.show();
   console.writeln( "" );
   console.writeln( "============================================================" );
   console.noteln( "                       ASTROTEMPS" );
   console.writeln( "                    AutoProcessing Tool" );
   console.writeln( "                         v" + VERSION );
   console.writeln( "============================================================" );
   console.writeln( "" );
}
function logStep( text )
{
   console.writeln( "" );
   console.writeln( "------------------------------------------------------------" );
   console.writeln( text );
   console.writeln( "------------------------------------------------------------" );
}
function clampValue( x, a, b )
{
   return Math.max( a, Math.min( b, x ) );
}
function pushUnique( array, value )
{
   for ( var i = 0; i < array.length; ++i )
      if ( array[i] == value )
         return;
   array.push( value );
}
function uniqueImageId( baseId )
{
   var id = baseId;
   var i = 1;
   while ( !ImageWindow.windowById( id ).isNull )
      id = baseId + "_" + i++;
   return id;
}
function TAP_collectGarbage( label )
{
   try { CoreApplication.processEvents(); } catch ( e0 ) {}
   // V8 manages garbage collection autonomously; no explicit gc() call.
   try { CoreApplication.processEvents(); } catch ( e2 ) {}
   if ( label )
      console.writeln( "Memory cleanup checkpoint: " + label );
}

function TAP_resolveEnumValue( instance, ctor, candidateNames, fallback )
{
   if ( candidateNames == null )
      candidateNames = [];
   if ( typeof candidateNames == "string" )
      candidateNames = [ candidateNames ];

   for ( var i = 0; i < candidateNames.length; ++i )
   {
      var n = candidateNames[i];
      try
      {
         if ( instance != null && typeof instance[n] == "number" )
            return instance[n];
      }
      catch ( e0 ) {}
      try
      {
         if ( ctor != null && typeof ctor[n] == "number" )
            return ctor[n];
      }
      catch ( e1 ) {}
      try
      {
         if ( ctor != null && ctor.prototype != null && typeof ctor.prototype[n] == "number" )
            return ctor.prototype[n];
      }
      catch ( e2 ) {}
   }

   return fallback;
}


function TAP_directSPCCAvailable()
{
   return typeof SpectrophotometricColorCalibration == "function";
}

function TAP_componentAvailable( name )
{
   switch ( name )
   {
   case "BlurXTerminator":
      return typeof BlurXTerminator != "undefined";
   case "NoiseXTerminator":
      return typeof NoiseXTerminator != "undefined";
   case "StarXTerminator":
      return typeof StarXTerminator != "undefined";
   case "StarNet2":
      return typeof StarNet2 != "undefined";
   case "SpectrophotometricColorCalibration":
      return TAP_directSPCCAvailable();
   case "AutomaticBackgroundExtractor":
      return typeof AutomaticBackgroundExtractor != "undefined";
   case "DynamicBackgroundExtraction":
      return typeof DynamicBackgroundExtraction != "undefined";
   case "BackgroundNeutralization":
      return typeof BackgroundNeutralization != "undefined";
   case "NarrowbandNormalization":
      return typeof NarrowbandNormalization == "function";
   case "RangeSelection":
      return typeof RangeSelection == "function";
   case "HDRMultiscaleTransform":
      return typeof HDRMultiscaleTransform == "function";
   case "CurvesTransformation":
      return typeof CurvesTransformation == "function";
   case "ATrousWaveletTransformV1":
      return typeof ATrousWaveletTransformV1 != "undefined";
   case "HistogramTransformation":
      return typeof HistogramTransformation != "undefined";
   case "PixelMath":
      return typeof PixelMath != "undefined";
   case "Cosmic Clarity - SASpro":
      // The JavaScript bridge is integrated. CLI/executable availability can
      // only be established reliably when the selected SASpro stage launches.
      return typeof runCosmicClarityViaSasproCLI == "function";
   case "Lighthouse":
      return typeof DialogUI == "function";
   }
   return true;
}

function TAP_stageRequiredComponents( stageId, s )
{
   var a = [];

   switch ( stageId )
   {
   case "optical":
      a.push( s.opticalEngine == ENGINE_SASPRO ? "Cosmic Clarity - SASpro" : "BlurXTerminator" );
      break;

   case "adbe":
      if ( s.adbeEngine == ADBE_ENGINE_GRAXPERT )
         a.push( "GraXpert CLI" );
      else
      {
         a.push( "AutomaticBackgroundExtractor" );
         a.push( "DynamicBackgroundExtraction" );
      }
      break;

   case "spcc":
      a.push( "SpectrophotometricColorCalibration" );
      break;

   case "blurx":
      a.push( s.sharpenEngine == ENGINE_SASPRO ? "Cosmic Clarity - SASpro" : "BlurXTerminator" );
      break;

   case "noisex":
      a.push( s.noiseEngine == ENGINE_SASPRO ? "Cosmic Clarity - SASpro" : "NoiseXTerminator" );
      break;

   case "starx":
      a.push( s.starRemovalEngine == STAR_ENGINE_STARNET ? "StarNet2" : "StarXTerminator" );
      break;

   case "findbg":
      a.push( "BackgroundNeutralization" );
      break;

   case "nbn":
      a.push( "NarrowbandNormalization" );
      break;

   case "rangehdr":
      a.push( "RangeSelection" );
      a.push( "HDRMultiscaleTransform" );
      break;

   case "maskscurves":
      a.push( "PixelMath" );
      a.push( "CurvesTransformation" );
      break;

   case "statstretch":
      a.push( "PixelMath" );
      break;

   case "lighthouse":
      a.push( "Lighthouse" );
      break;

   case "dse":
      a.push( "ATrousWaveletTransformV1" );
      a.push( "HistogramTransformation" );
      break;

   case "starstretch":
   case "screenstars":
      a.push( "PixelMath" );
      break;
   }

   return a;
}

function TAP_firstMissingComponentForStage( stageId, s )
{
   var a = TAP_stageRequiredComponents( stageId, s );
   for ( var i = 0; i < a.length; ++i )
      if ( !TAP_componentAvailable( a[i] ) )
         return a[i];
   return "";
}

function validateRequiredIcons( s )
{
   // Kept under its historical function name so existing dialog code and saved
   // instances remain compatible. It now validates installed scripts/processes,
   // not Workspace Process Icons.
   var missing = [];
   var order = s.customizeOrder
      ? TAP_normalizeExecutionOrder( s.executionOrder )
      : TAP_DEFAULT_EXECUTION_ORDER.slice( 0 );

   for ( var i = 0; i < order.length; ++i )
   {
      var stageId = order[i];
      if ( !TAP_isStageEnabled( stageId, s ) )
         continue;

      var a = TAP_stageRequiredComponents( stageId, s );
      for ( var j = 0; j < a.length; ++j )
         if ( !TAP_componentAvailable( a[j] ) && missing.indexOf( a[j] ) < 0 )
            missing.push( a[j] );
   }

   return missing;
}

function TAP_promptMissingComponent( name )
{
   var r = ( new MessageBox(
      "Script/Process " + name + " not found! Proceed with the workflow?",
      "AstroTemps AutoProcessing Tool",
      StdIcon_Error,
      StdButton_Yes,
      StdButton_No
   ) ).execute();

   return r == StdButton_Yes;
}

function TAP_errorText( error )
{
   try
   {
      if ( error === undefined )
         return "Unknown error: the called process threw undefined.";
      if ( error === null )
         return "Unknown error: the called process threw null.";
      if ( typeof error == "string" )
         return error.length > 0 ? error : "Unknown empty-string error.";
      if ( typeof error.message == "string" && error.message.length > 0 )
         return error.message;
      return String( error );
   }
   catch ( e )
   {
      return "Unknown error object.";
   }
}

function TAP_runtimeMissingComponentName( stageId, s, error )
{
   var msg = TAP_errorText( error );

   var lower = msg.toLowerCase();

   // Be conservative here. Runtime messages such as
   // "SPCC transmission curve not found" or "NoFunction is not defined"
   // are real execution errors, not missing installed processes, and should
   // reach the user verbatim instead of being collapsed into a generic
   // "Script/Process X not found" dialog.
   var looksMissing =
      lower.indexOf( "is not installed" ) >= 0 ||
      lower.indexOf( "is not available to pjsr" ) >= 0 ||
      lower.indexOf( "unable to locate" ) >= 0 ||
      lower.indexOf( "no auto-detect launcher" ) >= 0 ||
      lower.indexOf( "launcher failed" ) >= 0 ||
      lower.indexOf( "cannot find" ) >= 0 ||
      lower.indexOf( "script/process " ) >= 0;

   if ( !looksMissing )
      return "";

   var a = TAP_stageRequiredComponents( stageId, s );
   return a.length > 0 ? a[0] : TAP_STAGE_LABELS[stageId];
}

function TAP_userStopError( stageId, componentName )
{
   var e = new Error(
      "Workflow stopped by user at " + TAP_STAGE_LABELS[stageId] +
      " because " + componentName + " is not available."
   );
   e.tapUserStop = true;
   return e;
}

function isAstrometricPropertyId( id )
{
   id = String( id );
   return id.indexOf( "PCL:AstrometricSolution" ) == 0 ||
          id.indexOf( "PCL/AstrometricSolution" ) == 0;
}
function hasAstrometricProperties( view )
{
   try
   {
      var properties = view.properties;
      if ( properties == null )
         return false;
      for ( var i = 0; i < properties.length; ++i )
         if ( isAstrometricPropertyId( properties[i] ) )
            return true;
   }
   catch ( e )
   {
   }
   return false;
}
function copyViewProperties( sourceView, targetView )
{
   console.writeln( "Copying image properties..." );
   var properties;
   try
   {
      properties = sourceView.properties;
   }
   catch ( e )
   {
      console.warningln( "WARNING: Could not enumerate source image properties." );
      return { copied: 0, failed: 0, astrometric: 0 };
   }
   if ( properties == null )
      return { copied: 0, failed: 0, astrometric: 0 };
   var copied = 0;
   var failed = 0;
   var astrometric = 0;
   for ( var i = 0; i < properties.length; ++i )
   {
      var id = String( properties[i] );
      try
      {
         var value = sourceView.propertyValue( id );
         targetView.setPropertyValue( id, value );
         try
         {
            var attrs = sourceView.propertyAttributes( id );
            if ( typeof targetView.setPropertyAttributes == "function" )
               targetView.setPropertyAttributes( id, attrs );
         }
         catch ( attributeError )
         {
         }
         ++copied;
         if ( isAstrometricPropertyId( id ) )
            ++astrometric;
      }
      catch ( propertyError )
      {
         ++failed;
         if ( isAstrometricPropertyId( id ) )
         {
            console.warningln( "WARNING: Could not copy astrometric property: " + id );
            console.warningln( propertyError.message );
         }
      }
   }
   console.writeln( "Image properties copied : " + copied );
   if ( failed > 0 )
      console.writeln( "Properties skipped      : " + failed );
   console.writeln( "Astrometric properties  : " + astrometric );
   return { copied: copied, failed: failed, astrometric: astrometric };
}
function createWorkingCopy( sourceView )
{
   logStep( "[0] Create Working Copy" );
   var sourceWindow = sourceView.window;
   var sourceImage = sourceView.image;
   var sourceHadAstrometry = TAP_hasAstrometricSolution( sourceView );
   var newId = uniqueImageId( sourceView.id + "_work" );
   console.writeln( "Source astrometric solution: " + ( sourceHadAstrometry ? "YES" : "NO" ) );
   console.writeln( "Creating Working Copy..." );
   console.writeln( "Source : " + sourceView.id );
   console.writeln( "Target : " + newId );
   var copyWindow = new ImageWindow(
      1, 1,
      sourceImage.numberOfChannels,
      32,
      true,
      sourceImage.isColor,
      newId
   );
   if ( copyWindow == null || copyWindow.isNull )
      throw new Error( "PixInsight could not create the Working Copy window." );
   var copyView = copyWindow.mainView;
   var processStarted = false;
   try
   {
      copyView.beginProcess( UndoFlag_NoSwapFile );
      processStarted = true;
      copyView.image.assign( sourceImage );
      copyView.endProcess();
      processStarted = false;
   }
   catch ( error )
   {
      if ( processStarted )
      {
         try { copyView.endProcess(); } catch ( endError ) {}
      }
      try { copyWindow.forceClose(); } catch ( closeError ) {}
      throw new Error( "Could not copy image data to Working Copy.\n\n" + error.message );
   }
   console.writeln( "Pixel data copied." );
   try
   {
      copyWindow.keywords = sourceWindow.keywords;
      console.writeln( "FITS keywords copied." );
   }
   catch ( keywordError )
   {
      console.warningln( "WARNING: Could not copy FITS keywords." );
      console.warningln( keywordError.message );
   }
   var propertyResult = copyViewProperties( sourceView, copyView );

   // Astrometric solutions are not guaranteed to be represented only by View
   // properties. On PixInsight 1.9.4, copy the complete WCS solution explicitly
   // when the source window is solved.
   var copyHasAstrometry = TAP_hasAstrometricSolution( copyView );
   if ( sourceHadAstrometry && !copyHasAstrometry )
   {
      try
      {
         if ( typeof copyWindow.copyAstrometricSolution == "function" )
            copyWindow.copyAstrometricSolution( sourceWindow );
      }
      catch ( eAstrometryCopy )
      {
         console.warningln( "WARNING: explicit astrometric-solution copy failed: " + eAstrometryCopy.message );
      }
      copyHasAstrometry = TAP_hasAstrometricSolution( copyView );
   }

   console.writeln( "Working Copy astrometric solution: " + ( copyHasAstrometry ? "YES" : "NO" ) );
   if ( sourceHadAstrometry && !copyHasAstrometry )
   {
      try { copyWindow.forceClose(); } catch ( closeAstrometryError ) {}
      throw new Error(
         "The source image has an astrometric solution, but it could not be transferred to the Working Copy.\n\n" +
         "SPCC would fail on the cloned image."
      );
   }
   copyWindow.show();
   copyWindow.bringToFront();
   copyWindow.zoomToOptimalFit();
   CoreApplication.processEvents();
   console.writeln( "" );
   console.writeln( "Working Copy created successfully." );
   console.writeln( "Original image : " + sourceView.id );
   console.writeln( "Working image  : " + copyView.id );
   console.writeln( "Dimensions     : " + copyView.image.width + " x " + copyView.image.height );
   console.writeln( "Channels       : " + copyView.image.numberOfChannels );
   console.writeln( "View Properties: " + propertyResult.copied + " copied" );
   console.writeln( "Astrometry     : " + ( sourceHadAstrometry ? "preserved" : "source image was not solved" ) );
   console.writeln( "Original integration preserved." );
   return copyView;
}

// =====================================================================
// PROCESS SNAPSHOT / BACKUP COPIES
// =====================================================================

function TAP_backupBaseId( viewId )
{
   var m = String( viewId ).match( /^(.*)_work(?:_\d+)?$/ );
   return m != null ? m[1] : String( viewId );
}

function createProcessSnapshot( sourceView, suffix )
{
   if ( sourceView == null || sourceView.isNull )
      throw new Error( "Cannot create process snapshot: invalid source view." );

   var baseId = TAP_backupBaseId( sourceView.id );
   var newId = uniqueImageId( baseId + "_" + suffix );
   var sourceWindow = sourceView.window;
   var sourceImage = sourceView.image;

   console.writeln( "" );
   console.writeln( "Creating process backup: " + newId );

   var copyWindow = new ImageWindow(
      1, 1,
      sourceImage.numberOfChannels,
      32,
      true,
      sourceImage.isColor,
      newId
   );

   if ( copyWindow == null || copyWindow.isNull )
      throw new Error( "PixInsight could not create process backup: " + newId );

   var copyView = copyWindow.mainView;
   var processStarted = false;

   try
   {
      copyView.beginProcess( UndoFlag_NoSwapFile );
      processStarted = true;
      copyView.image.assign( sourceImage );
      copyView.endProcess();
      processStarted = false;
   }
   catch ( error )
   {
      if ( processStarted )
      {
         try { copyView.endProcess(); } catch ( e1 ) {}
      }
      try { copyWindow.forceClose(); } catch ( e2 ) {}
      throw new Error(
         "Could not copy image data to process backup '" + newId + "'.\n\n" +
         error.message
      );
   }

   try { copyWindow.keywords = sourceWindow.keywords; } catch ( e3 ) {}
   try { copyViewProperties( sourceView, copyView ); } catch ( e4 ) {}
   try
   {
      if ( TAP_hasAstrometricSolution( sourceView ) &&
           !TAP_hasAstrometricSolution( copyView ) &&
           typeof copyWindow.copyAstrometricSolution == "function" )
         copyWindow.copyAstrometricSolution( sourceWindow );
   }
   catch ( eAstrometrySnapshot ) {}
   try { copyView.stf = sourceView.stf; } catch ( e5 ) {}

   copyWindow.show();

   try { sourceView.window.bringToFront(); } catch ( e6 ) {}

   console.writeln( "Backup created: " + newId );
   CoreApplication.processEvents();

   return copyView;
}

function createProcessSnapshotIfEnabled( sourceView, settings, suffix )
{
   if ( settings.backupEachProcess )
      return createProcessSnapshot( sourceView, suffix );
   return null;
}

function applyAutoSTF( view, linked )
{
   if ( !view.image.isColor || view.image.numberOfNominalChannels < 3 )
   {
      console.warningln( "Auto STF skipped: target is not an RGB image." );
      return;
   }
   console.writeln( "" );
   console.writeln( "Applying RGB " + ( linked ? "Linked" : "Unlinked" ) + " Auto STF..." );
   var shadowsClipping = -1.25;
   var targetBackground = 0.25;
   var median = view.computeOrFetchProperty( "Median" );
   var mad = view.computeOrFetchProperty( "MAD" );
   if ( median == null || mad == null )
      throw new Error( "Could not obtain Median/MAD statistics for Auto STF." );
   mad.mul( 1.4826 );
   var c0 = [ 0.0, 0.0, 0.0 ];
   var m = [ 0.5, 0.5, 0.5 ];
   var i;
   if ( linked )
   {
      var med = 0.0;
      var dev = 0.0;
      for ( i = 0; i < 3; ++i )
      {
         med += median.at( i );
         dev += mad.at( i );
      }
      med /= 3.0;
      dev /= 3.0;
      if ( med < 0.5 )
      {
         var linkedC0 = Math.range( med + shadowsClipping * dev, 0.0, 1.0 );
         var linkedM = Math.mtf( targetBackground, med - linkedC0 );
         for ( i = 0; i < 3; ++i )
         {
            c0[i] = linkedC0;
            m[i] = linkedM;
         }
      }
      else
      {
         var linkedC1 = Math.range( med - shadowsClipping * dev, 0.0, 1.0 );
         var linkedM2 = 1.0 - Math.mtf( targetBackground, linkedC1 - med );
         for ( i = 0; i < 3; ++i )
         {
            c0[i] = 0.0;
            m[i] = linkedM2;
         }
      }
   }
   else
   {
      for ( i = 0; i < 3; ++i )
      {
         var channelMedian = median.at( i );
         var channelMAD = mad.at( i );
         if ( channelMedian < 0.5 )
         {
            c0[i] = Math.range( channelMedian + shadowsClipping * channelMAD, 0.0, 1.0 );
            m[i] = Math.mtf( targetBackground, channelMedian - c0[i] );
         }
         else
         {
            var channelC1 = Math.range( channelMedian - shadowsClipping * channelMAD, 0.0, 1.0 );
            c0[i] = 0.0;
            m[i] = 1.0 - Math.mtf( targetBackground, channelC1 - channelMedian );
         }
      }
   }
   var STF = new ScreenTransferFunction;
   STF.STF = [
      [ c0[0], 1.0, m[0], 0.0, 1.0 ],
      [ c0[1], 1.0, m[1], 0.0, 1.0 ],
      [ c0[2], 1.0, m[2], 0.0, 1.0 ],
      [ 0.0, 1.0, 0.5, 0.0, 1.0 ]
   ];
   if ( !STF.executeOn( view, false ) )
      throw new Error( "ScreenTransferFunction execution failed." );
   console.writeln( "Auto STF applied: RGB " + ( linked ? "Linked" : "Unlinked" ) );
   CoreApplication.processEvents();
}

// =====================================================================
// PixInsight 1.9.4 SPCC / ImageSolver helpers
// =====================================================================

function TAP_safeString( v )
{
   try
   {
      if ( v == null ) return "";
      return String( v );
   }
   catch ( e )
   {
      return "";
   }
}

function TAP_hasAstrometricSolution( view )
{
   if ( view == null || view.isNull )
      return false;

   try
   {
      if ( view.window != null && !view.window.isNull &&
           typeof view.window.hasAstrometricSolution != "undefined" &&
           view.window.hasAstrometricSolution )
         return true;
   }
   catch ( e0 ) {}

   return hasAstrometricProperties( view );
}

function TAP_ensureAstrometricSolution( view )
{
   if ( TAP_hasAstrometricSolution( view ) )
   {
      console.noteln( "Astrometric solution detected. ImageSolver skipped." );
      return;
   }

   console.warningln( "No existing astrometric solution detected." );
   console.noteln( "AstroTemps policy: running embedded V8 ImageSolver automatically before SPCC." );
   console.writeln( "ImageSolver V8 compatibility: jsAbortable host symbol = " +
                    ( typeof jsAbortable != "undefined" ? "available" : "not exposed; using Console abort API" ) );
   view.window.bringToFront();
   CoreApplication.processEvents();

   try
   {
      let solver = new ImageSolver;
      solver.Init( view.window, false /*prioritizeSettings*/ );

      if ( solver.error )
         throw new Error( "ImageSolver could not initialize from the available image metadata." );

      let md = solver.metadata;
      let seedOK =
         md != null &&
         isFinite( md.ra ) &&
         isFinite( md.dec ) &&
         isFinite( md.resolution ) &&
         md.resolution > 0;

      if ( !seedOK )
         throw new Error(
            "ImageSolver has no valid coordinate/scale seed. " +
            "The image needs usable RA/Dec and image-scale metadata, or saved ImageSolver settings." );

      console.writeln( format(
         "ImageSolver seed: RA %.6f deg, Dec %.6f deg, scale %.3f arcsec/px",
         md.ra, md.dec, md.resolution * 3600 ) );

      if ( typeof solver.solverCfg.catalog == "string" &&
           solver.solverCfg.catalog.indexOf( "_XPSD" ) >= 0 )
      {
         console.warningln(
            "Saved ImageSolver catalog '" + solver.solverCfg.catalog +
            "' is an XPSD catalog. AstroTemps embedded V8 mode will use " +
            "automatic online catalog selection instead." );
         solver.solverCfg.catalogMode = CatalogMode.prototype.Automatic;
      }

      if ( !solver.SolveImage( view.window ) )
      {
         let solverDetails =
            solver.lastError && solver.lastError.length > 0
               ? solver.lastError
               : "ImageSolver returned false without a detailed engine message.";

         throw new Error(
            "ImageSolver was unable to solve the selected image automatically.\n" +
            solverDetails );
      }

      try { solver.metadata.SaveSettings(); } catch ( eSave ) {}
      solver = null;
   }
   catch ( e )
   {
      throw new Error(
         "Automatic ImageSolver failed before SPCC.\n\n" +
         "The embedded V8 solver uses image metadata plus your saved PixInsight solver settings. " +
         "If the image has no usable coordinates/scale seed, solve it once manually or provide valid acquisition metadata.\n\n" +
         "Details: " + TAP_errorText( e )
      );
   }

   CoreApplication.processEvents();

   if ( !TAP_hasAstrometricSolution( view ) )
      throw new Error( "ImageSolver finished, but no astrometric solution was detected on the target image." );

   console.noteln( "ImageSolver completed successfully. Astrometric solution is now attached to the working image." );
}

function TAP_spccDatabaseCandidatePaths()
{
   var paths = [];

   try
   {
      var configured = Settings.read(
         "ModuleData/ColorCalibration/FiltersDatabaseFilePath",
         DataType_UCString
      );
      configured = TAP_safeString( configured );
      if ( configured.length > 0 ) paths.push( configured );
   }
   catch ( e0 ) {}

   // The configured Settings path above is preferred.
   // Do not probe the legacy application-directory property here: it is
   // not exposed by PixInsight 1.9.4 Lockhart's PJSR/V8 binding and produces
   // a warning at script load time. Fall back to common installation paths.
   paths.push( "C:/Program Files/PixInsight/library/filters.xspd" );
   paths.push( "C:/Program Files (x86)/PixInsight/library/filters.xspd" );
   paths.push( "/Applications/PixInsight/PixInsight.app/Contents/Resources/library/filters.xspd" );
   paths.push( "/Applications/PixInsight/PixInsight.app/Contents/library/filters.xspd" );
   paths.push( "/opt/PixInsight/library/filters.xspd" );
   paths.push( "/usr/local/PixInsight/library/filters.xspd" );

   return paths;
}

