function TAP_spccDecodeXml( value )
{
   return TAP_safeString( value )
      .replace( /&quot;/g, '"' )
      .replace( /&apos;/g, "'" )
      .replace( /&amp;/g, "&" )
      .replace( /&lt;/g, "<" )
      .replace( /&gt;/g, ">" )
      .replace( /^\s+|\s+$/g, "" );
}

function TAP_spccCanonicalName( value )
{
   return TAP_spccDecodeXml( value )
      .replace( /\u00a0/g, " " )
      .replace( /\s+/g, " " )
      .replace( /^\s+|\s+$/g, "" )
      .toLowerCase();
}

function TAP_spccXmlField( attrs, body, fieldName )
{
   var a = new RegExp( "\\\\b" + fieldName + "\\\\s*=\\\\s*\\\"([^\\\"]*)\\\"", "i" ).exec( attrs || "" );
   if ( a != null )
      return TAP_spccDecodeXml( a[1] );

   var t = new RegExp(
      "<" + fieldName + "\\\\b[^>]*>([\\\\s\\\\S]*?)</" + fieldName + ">",
      "i"
   ).exec( body || "" );
   if ( t != null )
      return TAP_spccDecodeXml( t[1].replace( /<[^>]+>/g, " " ) );

   return "";
}

function TAP_spccCurveFromVectors( wavelengthText, transmissionText )
{
   var w = TAP_safeString( wavelengthText ).split( /[\s,;]+/ );
   var t = TAP_safeString( transmissionText ).split( /[\s,;]+/ );
   var wp = [];
   var tp = [];
   var i;

   for ( i = 0; i < w.length; ++i )
      if ( w[i].length > 0 && isFinite( Number( w[i] ) ) )
         wp.push( Number( w[i] ) );

   for ( i = 0; i < t.length; ++i )
      if ( t[i].length > 0 && isFinite( Number( t[i] ) ) )
         tp.push( Number( t[i] ) );

   if ( wp.length < 2 || wp.length != tp.length )
      return "";

   var p = [];
   for ( i = 0; i < wp.length; ++i )
   {
      p.push( String( wp[i] ) );
      p.push( String( tp[i] ) );
   }
   return p.join( "," );
}

