            engine.execute(previewWindow.mainView, this.tempValue, this.tintValue, this.exposureValue, this.brightnessValue, this.contrastValue, this.value, this.highlightRecoveryValue, this.shadowValue, this.whiteValue, this.blackValue, this.satValue, this.vibranceValue, this.textureValue, this.clarityValue, this.dehazeValue, this.midtoneValue, this.midtoneLow, this.midtoneMid, this.midtoneHigh, this.lumMaskEnabled, this.lumMaskType, this.lumMaskDepth, this.lumMaskMode, this.lumMaskStrength, this.scnrValue, this.scnrInverse, this.clarityRadiusValue, this.nrLuminanceValue, this.nrDetailValue, this.nrContrastValue, this.nrColorValue, this.nrColorDetailValue, this.nrColorSmoothnessValue, this.scProtectionValue, lighthouseSelectionParamFromSettings(this, this.previewCrop), lighthouseWaveletParamFromSettings(this), lighthouseChannelGainsFromSettings(this), 1, (skipSelectiveColor === true) ? null : lighthouseSelColorParamFromSettings(this), lighthouseWatermarkParamFromSettings(this), lighthouseCurvesParamFromSettings(this), (skipHSL === true) ? null : lighthouseHSLParamFromSettings(this));

