   this.syncValuesFromControls = function()
   {
      this.tempValue = this.tempSlider.value;
      this.tintValue = this.tintSlider.value;
      this.exposureValue = this.exposureSlider.value;
      this.brightnessValue = this.brightnessSlider.value;
      this.contrastValue = this.contrastSlider.value;
      this.value = this.slider.value;
      this.highlightRecoveryValue = this.highlightRecoverySlider.value;
      this.scProtectionValue = this.scProtectionSlider.value;
      this.shadowValue = this.shadowSlider.value;
      this.whiteValue = this.whiteSlider.value;
      this.blackValue = this.blackSlider.value;
      this.satValue = this.satSlider.value;
      this.vibranceValue = this.vibranceSlider.value;
      this.textureValue = this.textureSlider.value;
      this.clarityValue = this.claritySlider.value;
      this.clarityRadiusValue = this.clarityRadiusSlider.value;
      this.dehazeValue = this.dehazeSlider.value;
      this.midtoneValue = this.midtoneSlider.value;
      this.scnrValue = this.scnrSlider.value;
      this.nrLuminanceValue = this.nrLuminanceSlider.value;
      this.nrDetailValue = this.nrDetailSlider.value;
      this.nrContrastValue = this.nrContrastSlider.value;
      this.nrColorValue = this.nrColorSlider.value;
      this.nrColorDetailValue = this.nrColorDetailSlider.value;
      this.nrColorSmoothnessValue = this.nrColorSmoothnessSlider.value;
      this.scnrInverse = this.scnrInverse_CheckBox.checked;
      this.midtoneLow = this.midtoneLow_CheckBox.checked;
      this.midtoneMid = this.midtoneMid_CheckBox.checked;
      this.midtoneHigh = this.midtoneHigh_CheckBox.checked;
      this.lumMaskEnabled = this.lumMaskEnabled_CheckBox.checked;
      this.lumMaskType = lighthouseLuminosityMaskType(this.lumMaskType_ComboBox.currentItem);
      this.lumMaskDepth = lighthouseLuminosityMaskDepth(this.lumMaskDepth_ComboBox.currentItem + 1);
      this.lumMaskMode = lighthouseLuminosityMaskMode(this.lumMaskMode_ComboBox.currentItem);
      this.lumMaskStrength = this.lumMaskStrengthSlider.value;
      this.lumMaskShow = this.lumMaskShow_CheckBox.checked;
      this.lumMaskShowGray = this.lumMaskShowGray_CheckBox.checked;
      this.createNewImage = this.createNew_CheckBox.checked;
      this.useFastPreview = this.fastPreview_CheckBox.checked;
      this.useFullResPreview = this.fullResPreview_CheckBox.checked;
      if (this.accordion_CheckBox)
         this.accordionMode = this.accordion_CheckBox.checked;
      // Per-region feather/white-mask/strength live on each region (edited live via
      // setActiveRegionField); syncSelectionFromPreview mirrors the whole list.
      if (this.syncWaveletValuesFromControls)
         this.syncWaveletValuesFromControls();
      if (this.syncSelColorValuesFromControls)
         this.syncSelColorValuesFromControls();

      if (this.syncHSLValuesFromControls)
         this.syncHSLValuesFromControls();
      if (this.syncWatermarkValuesFromControls)
         this.syncWatermarkValuesFromControls();
      if (this.syncSelectionFromPreview)
         this.syncSelectionFromPreview();
   };

